quests[25975] = { id = 25975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einforderung der Schätze", description = "Wir haben unsere ersehnte Verstärkung, aber immer noch keine Ahnung, wie wir sie bezahlen sollen. Und diese Art von Hilfe ist nicht ganz billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für unsere Zwecke zurückzustehlen.", sourceObjective = "Sammelt 6 Stück Tiefenflossenbeute.", progress = "Wie viel Beute konntet Ihr zurückfordern, {name}?", completion = "Das sollte vorerst reichen. Wir wissen ja, wo es bei Bedarf mehr gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25976] = { id = 25976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einforderung der Schätze", description = "Blut und Donner! Wir haben unsere ersehnte Verstärkung, aber wir müssen sie leider auch bezahlen. Das wird sicher nicht billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für die Horde zurückzustehlen.\n\nHöllschreis Augen ruhen auf Euch, {name}!", sourceObjective = "Sammelt 6 Stück Tiefenflossenbeute.", progress = "Wie viel Beute konntet Ihr zurückfordern, {name}?", completion = "Das ist ganz schön viel. Und wir wissen ja, wo es bei Bedarf mehr gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25977] = { id = 25977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standartenmäßiger Tag für Azrajar", description = "{name}, die Schlangen sind hinter unserer Armee her. Geht nach Nordwesten zum Tiefenflossengrat und steckt dem Futzi, den sie ihren Boss nennen, ein bisschen Holz zwischen die Rippen.\n\nWenn sie das sehen, werden sie Angst bekommen und abhauen mit dem Schwanz zwischen den Bei... ach nee, Beine haben sie ja gar keine.", sourceObjective = "Rammt die Standarte der Allianz in Tiefenrufer Azrajars Leichnam.", completion = "Saubere Arbeit! \"O'zapft is der General!\", würde ich mal sagen.\n\n<Der Leutnant schüttelt mit dem Kopf und grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25978] = { id = 25978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Eis eingeschlossen", description = "Khurgorn sagt, der Kataklysmus habe das Gleichgewicht der Elemente auf der ganzen Welt erschüttert. Der Helmsbettsee im Süden war einmal wunderschön und ruhig, doch nun wimmelt es dort von wütenden Wasserelementaren. Als sie begannen, den See zu verlassen, schickte ich Truppen dorthin, um sie abzulenken, aber die meisten wurden in Eisblöcken eingefroren.\n\nWenn wir sie befreien können, werden sie sich wahrscheinlich erholen. Ich kann niemanden für eine zweite Expedition zum See entbehren. Würdet Ihr es versuchen?", sourceObjective = "Öffnet sechs eisige Gräber, um die gefrorenen Gebirgsjäger am Helmsbettsee zu befreien.", completion = "Ihr habt es geschafft! Die Gebirgsjäger kehren ins Lager zurück. Unsere Sanitäter werden viel zu tun haben. Wir stehen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25979] = { id = 25979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glättet die Wogen", description = "Die Elemente sind aufgewühlt, {class}. Der Kataklysmus hat die schlafenden Wassergeister im Helmsbettsee südlich von hier geweckt. Sie sind wütend, verwirrt und nicht gewillt, sich meine Bitten anzuhören.\n\nIch habe alles versucht, um sie zu beruhigen und davon zu überzeugen, die Gebirgsjäger des Unteroffiziers nicht mehr anzugreifen.\n\nIch sage das nur ungern, aber uns bleibt keine andere Wahl -- wir müssen die Elementare töten.", sourceObjective = "Tötet 6 Woger des Helmbettsees am Helmbettsee.", completion = "Es fällt mir nicht leicht, Gewalt gegen die Elemente anzuwenden, deren Macht ich benutze, aber manchmal gibt es keinen anderen Weg. Wir sind zuerst den Bewohnern Dun Moroghs verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25980] = { id = 25980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standartenmäßiger Tag für Azrajar", description = "{name}, die Naga sind hinter unseren Streitmächten her. Ihr müsst für mich zurück nach Nordwesten zum Tiefenflossengrat gehen und unsere Standarte in ihren General, Tiefenrufer Azrajar stechen.\n\nSie werden vor Angst davon schwimmen, mit dem Schwanz zwischen den… äh. Na ja, Beine haben sie ja wohl nicht, oder?", sourceObjective = "Rammt die Standarte der Horde in Tiefenrufer Azrajars Leichnam.", completion = "Ihr habt ihn also richtig durchbohrt? Das hätte ich ja zu gerne gesehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25981] = { id = 25981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind gar keine Masken", description = "{name}, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Auch eine Art, an Sklaven zu kommen.\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen?", sourceObjective = "Sammelt 6 Köpfe eines Gnadenlosen.", progress = "Wie viele habt Ihr?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Stinken nur ganz schön.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", sourceObjectiveStatus = "unverified-source-field" }
quests[25982] = { id = 25982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind gar keine Masken", description = "{name}, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Wir müssen verhindern, dass sie hierher kommen!\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen? Bevorzugt tote Exemplare, schätze ich.", sourceObjective = "Sammelt 6 Köpfe eines Gnadenlosen.", progress = "Was stinkt hier so?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Eigentlich. Irgendwie sind sie fast schon niedlich.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", sourceObjectiveStatus = "unverified-source-field" }
quests[25983] = { id = 25983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kap", description = "Wir müssen diese Informationen zu Kapitän Taylor am Kap bringen. Er befindet sich im Nordwesten mit Erunak Steinsprecher und den Mitgliedern des Irdenen Rings.", sourceObjective = "Sprecht mit Kapitän Taylor am Kap in Vashj'ir.", completion = "Das sind verstörende Neuigkeiten, doch ich glaube, dass unsere Freunde vom Irdenen Ring einen Plan haben.\n\nUnd jetzt, da Ihr hier seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[25984] = { id = 25984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kap", description = "{name}, ich möchte, dass Ihr diese Informationen zu Legionär Nazgrim am Kap bringt. Er befindet sich im Nordwesten mit Erunak Steinsprecher und diesen Leuten vom Irdenen Ring.", sourceObjective = "Sprecht mit Legionär Nazgrim am Kap in Vashj'ir.", completion = "Ich würde meinen Ohren nicht trauen, wenn nicht Ihr der Überbringer dessen wärt, was dieser lästige Goblin zu sagen hat. Das ist in der Tat beunruhigend, aber ich glaube, dass unsere Freunde vom Irdenen Ring einige Ideen haben.\n\nUnd wo Ihr nun hier seid…", sourceObjectiveStatus = "unverified-source-field" }
quests[25985] = { id = 25985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingen über dem Hyjal", description = "{name}, ist es wahr, dass Ihr versuchen werdet, mit den Ahnen zu sprechen?\n\nSüdwestlich von hier befindet sich der Schrein von Aviana, der Mutter aller fliegenden Lebewesen. Dort lebt meine Lieblingslehrerin, Choluna. Ich habe noch nie jemanden kennengelernt, der so eins mit den Geistern dieser Welt war. Ihr könntet viel von ihr lernen!\n\nWegen der kürzlichen Angriffe ist der Schrein von der Außenwelt abgeschnitten. Aber aus der Luft könnt Ihr ganz einfach dorthin gelangen. Haltet nach dem größten Baum auf dem Hyjal Ausschau. Viel Glück!", sourceObjective = "Findet Choluna am Schrein von Aviana auf dem Hyjal.", completion = "Oh, Tiala schickt Euch? Was für eine herausragende Schülerin. Sie wird noch Großartiges erreichen.\n\nObwohl ich in Euch sogar noch mehr Potenzial spüre.\n\nBitte, bleibt doch eine Weile bei unserem Schrein. Es gibt viel zu tun, aber mit einem beunruhigten Gemüt lässt es sich kaum bewältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25986] = { id = 25986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am See", description = "Ihr wart eine große Hilfe bei der Sicherung der Minen und der Rettung der gefangenen Minenarbeiter.\n\nEs wird den Senat freuen, dass Ihr und Hauptmann Tharrans Gebirgsjäger Fortschritte bei der Sicherung Dun Moroghs gemacht habt.\n\nMich besorgt allerdings, dass ich keine Berichte von Unteroffizier Bahrum und seiner Abteilung erhalten habe. Sie wurden nach Osten geschickt, auf die Straße, die zum Helmsbettsee führt. Dort sollten sie einen kleinen Außenposten errichten. Würdet Ihr zu Bahrums Posten reisen und nach dem Unteroffizier sehen?", sourceObjective = "Sprecht mit Unteroffizier Bahrum an Bahrums Posten.", completion = "Gut, dass der Senator nicht allein hierhergekommen ist. Es ist gefährlich hier. Wir werden all die Hilfe brauchen, die wir kriegen können, um die Lage unter Kontrolle zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25987] = { id = 25987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt es auf", description = "He, {name}! Ich habe eine tolle Idee für eine Verkleidung. Nehmt einen dieser gnadenlosen Wasauchimmers und setzt ihn Euch auf den Kopf.\n\nWas kann dabei schon schiefgehen?\n\nSeid Ihr bereit, ihn aufzusetzen?", sourceObjective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", completion = "Was ist passiert? Das Ding war wohl nicht ganz tot! Vielleicht sollte ich einfach bei den mechanischen Dingen bleiben.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will sie keinesfalls in meiner Nähe haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25988] = { id = 25988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt es auf", description = "Ich habe eine tolle Idee für eine Verkleidung, aber ich brauche Eure Hilfe dabei, {name}. Nehmt einen dieser gnadenlosen Leichname und setzt ihn Euch auf den Kopf.\n\nIch weiß, ich weiß, aber es ist tot. Was kann dabei schon schiefgehen, außer dass Ihr ein, zwei Tage übel riecht?\n\nSeid Ihr bereit, ihn aufzusetzen?", sourceObjective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", completion = "Mein Fehler. Ich heiße nicht umsonst \"Fiasco\". Ich hätte wissen sollen, dass es nicht ganz tot ist, als es gezuckt hat.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will nicht, dass sie hier alles vollstinken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25989] = { id = 25989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang den Krebs", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet,... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", sourceObjective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "<Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.>\n\nEr sieht nicht besonders beeindruckend aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25990] = { id = 25990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25991] = { id = 25991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind nicht allein", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Hordesklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, {name}. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", sourceObjective = "Findet die Überlebenden der Horde in Nespirah in Vashj'ir.", completion = "{name}… Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[25992] = { id = 25992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnungslos ausrüstungslos", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", sourceObjective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Piekse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "<Hauptmann Übeldorn bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.>\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, {name}. Wir werden sie sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25993] = { id = 25993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Körpereinsatz", description = "<Legionär Nazgrim lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht findet Euer Schwert ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", sourceObjective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25994] = { id = 25994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch wertvoll", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", sourceObjective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n<Tulra verstaut die Perlen unter ihrer Rüstung.>\n\nUnd jetzt müssen Legionär Nazgrim und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25995] = { id = 25995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Idra'kess", description = "Meine Männer lassen nach, {name}. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Nordosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten. Höllschreis Augen ruhen auf Euch!", sourceObjective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Legionär Nazgrim hat mir den Rest berichtet.\n\n<Duarn schließt die Augen und nickt.>\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25996] = { id = 25996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung der Bestie", description = "Dank Euch und dem Legionär hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", sourceObjective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Höllschrei sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25997] = { id = 25997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimtücke der Dunkeleisenzwerge", description = "Eine Gruppe Dunkeleisenspione hat Eisenbands Truppenlager im Süden, hinter dem Helmsbettsee übernommen. Die Gebirgsjäger wären normalerweise in der Lage, sie aus Dun Morogh herauszuhalten, aber es herrscht gerade Chaos.\n\nDie Dunkeleisenzwerge wären Narren, wenn sie das nicht zu ihrem Vorteil nutzen würden. Wir müssen herausfinden, was sie planen und sie aufhalten, bevor sie Schaden anrichten.\n\nKönntet Ihr versuchen herauszufinden, was sie in Eisenbands Truppenlager machen?", sourceObjective = "Tötet 5 Spione der Dunkeleisenzwerge und erbeutet die Angriffspläne der Dunkeleisenzwerge von Hauptmann Beld in Eisenbands Truppenlager.", progress = "Was haben die Dunkeleisenzwerge vor?", completion = "Ich habe mir schon gedacht, dass sie nicht wegen der Aussicht hier sind.\n\n<Der Unteroffizier betrachtet die Pläne, die Ihr erbeutet habt. Seine Augen weiten sich.>\n\nDas ist ernster als befürchtet! Dies ist nicht nur ein Überfall. Die Dunkeleisenzwerge wollen die Verteidigungsbollwerke von Eisenschmiede lahmlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25998] = { id = 25998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Flugplatz", description = "Laut der Pläne, die Ihr erbeutet habt, planen die Dunkeleisenzwerge einen großangelegten Angriff auf den Flugplatz von Eisenschmiede! Der Rat hat einen Großteil unserer Streitkräfte nach Dun Morogh verlegt. Sie sollen sich dort um die Instabilität, die durch den Kataklysmus entstanden ist, kümmern. Die Verteidigungslinien des Flugplatzes sind geschwächt.\n\nWir müssen Euch so schnell wie möglich zum Flugplatz bringen. Nehmt die Straße zurück nach Westen, in Richtung des Steinbruchs Gol'Bolar und findet Mathel Rostzange. Er sollte eine Flugmaschine für Euch haben. Geht!", sourceObjective = "Steigt in Mathels Flugmaschine im Steinbruch Gol'Bolar.", completion = "Zum Glück seid Ihr hier, {name}. Der Flugplatz wird von Dunkeleisenzwergen angegriffen. Wir halten nicht mehr lange durch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25999] = { id = 25999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schritt für Schritt", description = "Den schmutzigen, nichtsnutzigen Nachtelfen ist es gelungen, unser ganzes Minenfeld auf dem Steinkrallenpass zu entschärfen. Jemand muss dorthin zurückgehen und die Minen wieder scharf machen! Diese Aufgabe ist perfekt für einen wertlosen Grunzer wie Euch geeignet, {name}. Hoffentlich jagt Ihr Euch dabei nicht selbst in die Luft.\n\nUnsere \"Elfentöter\" liegen überall auf dem Steinkrallenpass, unmittelbar nördlich von hier. Nehmt diesen Schraubenschlüssel und macht Euch an die Arbeit, Made.", sourceObjective = "Macht 8 Krom'gar \"Elfentöter\" scharf.", progress = "Was habt Ihr zu melden, Grunzer?", completion = "<Saurboz mustert Euch.>\n\nIhr habt noch alle Gliedmaßen. Das gab's noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26000] = { id = 26000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenforscher", description = "Schnell, {name}!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", sourceObjective = "Sprecht mit Gurrok in der Tiefennebelgrotte.", completion = "Ein… ein {race}? Hier?\n\nIch muss wahnsinnig sein…", sourceObjectiveStatus = "unverified-source-field" }
quests[26001] = { id = 26001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Sprengenieur", description = "Ihr seid wohl doch nicht völlig nutzlos. Vielleicht bewältigt Ihr sogar eine etwas wichtigere Aufgabe.\n\nVor rund zwei Tagen habe ich Sprengenieur Fusselpfiff zur Scherwindmine geschickt. Er sollte sich dort davon überzeugen, dass alles mit der Bombe nach Plan läuft und sich dann wieder hier melden. Zwei Tage und nichts...\n\nBegebt Euch in den Wald südlich von hier und findet ihn. Wenn er Glück hat, ist er tot.", sourceObjective = "Findet Sprengenieur Fusselpfiff.", completion = "Sprengenieur Fusselpfiff ist definitiv tot. Ist vielleicht besser so.\n\nEr scheint eine Notiz in der Hand zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26002] = { id = 26002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne der Allianz", description = "<Ihr zieht die Notiz aus Fusselpfiffs toten Fingern.>\n\nSie wissen Bescheid! Sie wissen von der Bombe. Planen Angriff auf Feste Krom'gar! Ich glaube, sie suchen mich. Werde nicht sterben wie ein Feigling. Ich werde kämpfen.\n\nIch glaube, da kommen sie! Ihre Anführerin ist eine Hochelfenjägerin namens Davinia. Sie sprach von den Angriffsplänen. Rächt mich, indem Ihr sie tötet und Euch die Pläne holt! Ihr Zelt steht östlich von hier, ganz in der Nähe.\n\nMöge Höllschrei über Euch wachen...", sourceObjective = "Erbeutet die Angriffspläne der Allianz von Jägerin Davinia.", progress = "Habt Ihr Fusselpfiff gefunden?", completion = "Verdammt schade... Er war ein guter Goblin.\n\n<Saurboz schüttelt seine Faust.>\n\n{name}, Ihr habt richtig gehandelt. Dank dieser Angriffspläne können wir uns vorbereiten. Ich möchte, dass Ihr die Pläne Oberanführer Krom'gar persönlich übergebt! Es sollte eine Beförderung für Euch drin sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26003] = { id = 26003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehren von den Verlorenen Inseln", description = "In den Wäldern südlich von hier lauern große Gefahren. Sie wimmeln von darnassischen Spähern - Assassinen, die aus Darnassus geschickt wurden, um uns zu töten. Vielleicht können wir den Spieß umdrehen.\n\nAls ich auf den Verlorenen Inseln festsaß, gab mir ein Goblin diese Infrarot-Hitzebrille. Mit ihr kann der Träger die Wärmesignatur bestimmter Kreaturen sehen. Nehmt die Brille und setzt sie in den Wäldern im Süden auf. Auf diese Weise werdet Ihr die Späher leicht entdecken können. Tötet so viele Ihr könnt! Für die Horde!", sourceObjective = "Tötet 12 Späher von Darnassus.", completion = "Gut gemacht, Bruder! Jetzt wissen sie, dass sie sich nicht an die Horde anschleichen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26004] = { id = 26004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feste Krom'gar", description = "Feste Krom'gar ist unsere Hauptoperationsbasis im Steinkrallengebirge. Von hier aus überwacht Oberanführer Krom'gar die militärischen Aktionen der Horde in dieser Region. Krom'gar leitet die Berichte aller Ereignisse direkt an den Kriegshäuptling weiter.\n\nDie Angriffspläne, die Ihr uns gebracht habt, beschreiben einen Angriff, der bald gegen die Feste Krom'gar geführt werden soll. Nehmt die Pläne und brecht zur Feste südwestlich von hier auf. Gebt sie dem Oberanführer.\n\nLebt wohl, {name}. Höllschrei wacht wahrlich über Euch.", sourceObjective = "Bringt die Angriffspläne der Allianz zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", progress = "Was hat diese Unterbrechung zu bedeuten? Wieso steht dieser Grunzer vor Oberanführer Krom'gar?", completion = "<Ihr gebt Oberanführer Krom'gar die Pläne.>\n\nHmm. Vielleicht steckt mehr in Euch, als es den Anschein hat. Vielleicht steckt in Euch ein Unteroffizier.\n\nRichtet Euren Blick auf Krom'gar Unteroffizier {name}, Soldaten. Er hat uns vor einem feigen Angriff der Allianz gewarnt. Einen Angriff, den wir NIEDERWERFEN werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26005] = { id = 26005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch frischer Luft", description = "Kapitän Taylor und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nHexasept hat die hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", sourceObjective = "Findet Kapitän Taylor auf der Voldrins Mut an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt es geschafft! Schön Euch zu sehen, {name}.\n\nEs ist ein tolles Gefühl, dem Wasser entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Ich bin mir sicher, dass viele der Jungs nach all den Strapazen alles geben würden, um umzudrehen und nach Hause fahren zu können. Aber wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Haltet Ihr bis zum Ende durch? Ich würde es Euch nicht übel nehmen, wenn Ihr die Nase voll hättet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26006] = { id = 26006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch frischer Luft", description = "Legionär Nazgrim und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nFiasco hat das hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", sourceObjective = "Findet Legionär Nazgrim auf der Höllenjuwel an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt es also in einem Stück geschafft, {class}.\n\nEs ist ein tolles Gefühl, diesem stinkenden Pfuhl entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Macht es Euch aber nicht zu bequem. Wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Hattet Ihr genug Ruhm für einen Tag oder stürzt Ihr Euch wieder in den Kampf, um Höllschrei Stolz zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26007] = { id = 26007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragung", description = "Dieser Krieger stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", sourceObjective = "Sprecht mit Gurrok und erfahrt etwas über seine Tortur.", completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26008] = { id = 26008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druckabbau", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Krieger inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, {name}. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", sourceObjective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Kriegern in der Umklammerung.", completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26009] = { id = 26009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchen und Zerstören", description = "Die Allianz rückt auf unsere Territorien im Steinkrallengebirge vor. Die Streitkräfte von Nordwacht haben unsere Blockade im Süden durchbrochen und besetzen nun das Scherwindtal westlich von hier. Im Norden werden wir von Nachtelfensoldaten angegriffen. All das muss aufhören!\n\nBegebt Euch ins Steinkrallengebirge und vernichtet alle Allianzsoldaten, die Euren Weg kreuzen. Ihr Tod soll als Warnung dienen.\n\nDas Steinkrallengebirge gehört der Horde!", sourceObjective = "Tötet 20 beliebige Soldaten der Allianz im Steinkrallengebirge.", completion = "Es wird noch viel Blut in dieser Erde versickern, bis der Krieg vorüber ist. Blut der Allianz...", sourceObjectiveStatus = "unverified-source-field" }
quests[26010] = { id = 26010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Asche", description = "Die Allianz wird immer unverschämter. Westlich von hier, im Scherwindtal, haben Truppen der Nordwacht ein Lager aufgeschlagen. Zweifellos bereiten sie sich auf den Angriff vor, den Ihr uns gemeldet habt, {name}. Soweit wird es nicht kommen!\n\nNehmt diesen Flammenwerfer. Den gleichen Flammenwerfer setzten meine Verbrenner ein, um unsere Feinde aus den Wäldern zu jagen. Zerstört damit die Zelte der Nordwacht. Lasst nur Asche zurück!", sourceObjective = "Zerstört 8 Zelte der Nordwacht mit Krom'gars Flammenwerfer.", completion = "Lok'tar! Allianzschweine!\n\n<Oberanführer Krom'gar spuckt auf den Boden.>\n\nGenießt Euren Sieg, er wird nicht lange währen. Euer Mut hat uns Zeit verschafft, aber mehr nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26011] = { id = 26011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feind der Horde: Marschall Paltrow", description = "Meine Späher haben die Ursache dieses neuesten Fiaskos gefunden: Marschall Paltrow. Er kommandiert das Vorauslager der Nordwacht im Scherwindtal westlich von hier. Eliminiert ihn. Damit entfernt Ihr einen wichtigen Feldkommandanten der Allianz aus der Gleichung.\n\nPaltrow muss sterben, {name}.", sourceObjective = "Tötet Marschall Paltrow.", completion = "Habt Ihr verdächtige Dokumente in Paltrows Lager gefunden? Vielleicht an seiner verwesenden Leiche? Jeder Hinweis auf die Angriffsmuster der Allianz wären bei der Schlacht ums Steinkrallengebirge von Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[26012] = { id = 26012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger im Wyrmruhtempel", description = "Mein alter Freund Krasus berichtet von grässlichen Vorkommnissen im Wyrmruhtempel in der Drachenöde. Sein Schreiben war kurz, doch es scheint, dass eine Art Angriff auf das Rubinsanktum unterhalb des Tempels stattgefunden hat.\n\nDringende Angelegenheiten hier in Dalaran halten mich davon ab, mich persönlich um die Sache zu kümmern, doch sind mir Berichte Eurer Heldentaten in der Zitadelle des Lichkönigs zu Ohren gekommen und Ihr seid zweifellos dieser Aufgabe gewachsen - vielleicht könntet Ihr an meiner statt Krasus behilflich sein?", sourceObjective = "Sprecht mit Krasus im Wyrmruhtempel in der Drachenöde.", completion = "Ich danke Euch, dass Ihr Rhonins Bitte gefolgt seid, tapferer Abenteurer.\n\nLasst mich Euch mitteilen, was uns über die jüngsten Geschehnisse bekannt ist. Jede Hilfe, die Ihr zu gewähren bereit seid, wird sehr geschätzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26013] = { id = 26013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Sanktum", description = "{race}, etwas Schreckliches ist im Rubinsanktum unterhalb des Tempels geschehen.\n\nDer Eingang zum Sanktum liegt in Ruinen und seine Wächter sind auf grausame Art und Weise erschlagen worden. Wir haben Kundschafter ausgesandt, um der Sache auf den Grund zu gehen, aber sie sind nicht zurückgekommen. Nun befürchte ich das Schlimmste.\n\nBetretet das Rubinsanktum und bringt in Erfahrung, was in der Heimat meines Schwarmes passiert ist. Sobald wir mehr Informationen haben, können wir unsere nächsten Schritte entsprechend planen.", sourceObjective = "Untersucht das Rubinsanktum unterhalb des Wyrmruhtempels.", completion = "Habt Dank, {class}, dafür, dass Ihr mich aus Baltharus' Klauen gerettet habt!\n\nAllerdings gibt es noch immer sehr viel zu tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[26014] = { id = 26014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Grabungslied", description = "Stillgestanden, <Gefreiter/Gefreite> {name}! Wir chaben kleine Problem!\n\nWir chaben geschickt Humphrey und Oskar Grabungslied zur Tiefenlichtkluft im Njordwesten, aber sie sind nicht zurückgekommen. Sie sollten ausspähen Umgebung, aber wir chaben verloren jeden Kontakt zu ihnen.\n\nEure Aufgabe, <Gefreiter/Gefreite> {name}, ist zu finden unsere Genossen und, falls sie noch ljeben, sie zu mir zurückzubringen!", sourceObjective = "Meldet Euch bei Humphrey Grabungslied in der Tiefenlichtkluft in Vashj'ir.", completion = "Natürlich sind wir noch nicht zurück! Wir haben ganz schön viele Rückschläge einstecken müssen… nicht zuletzt das Ableben meines geliebten Bruders Oskar.\n\n<Humphrey schnieft laut.>\n\nEr hat den Halt verloren und ist einfach davongetrieben, der Arme! Er wollte ein paar Fische für den Kapitän fangen, stattdessen wurde er weggespült und von einem dieser... dieser riesigen Aale gefressen! Uääääh hä hä häh hääääh!", sourceObjectiveStatus = "unverified-source-field" }
quests[26015] = { id = 26015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phosphorajagd", description = "Oskars letzter Wunsch, bevor er im Rachen dieses Großaals verschwand, war, dem Käpt'n Nahrung zu bringen. Also werden wir ihm diesen Wunsch erfüllen.\n\nMein Bruder hatte einen genialen Plan. Er hat beobachtet, wie diese Murlocs mit phosphoreszierenden Antennen Fische aus dem Schilf locken. Daraufhin hat er einen Weg gefunden, ein eigenes Gerät zu bauen. Ihr braucht nur etwas, das leuchtet.\n\nTötet die Krebse und Barsche am Grund der Kluft. Sie selbst sind nicht essbar, aber ihr Phosphora ist weitaus wertvoller als ihr Fleisch.", sourceObjective = "Besorgt Euch 6 Tiefenlichtphosphora von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", progress = "Wir brauchen genug Phosphora, um ein starkes Licht zu erschaffen. Ihr müsst heller leuchten, als diese Murlocs!", completion = "<Humphrey nimmt Euch das Phosphora ab und bringt es an einem ungewöhnlichen Gerät an.>\n\nSo. Wunderschön! Oskar wäre sehr stolz darauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26016] = { id = 26016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle aus dem Basislager", description = "Paltrow, errichtet einen Stützpunkt im Scherwindtal. Ein starker Bodenangriff ist lebenswichtig für unseren Feldzug! Wenn wir Krom'gar angreifen, werden Eure Männer für das Chaos und die Verwirrung sorgen, die unsere Gnomflugmaschinen brauchen, um nahe genug für einen Bombenangriff an die Orcfestung zu kommen.\n\nDie Flugmaschinen werden die Bombe von Krom'gar zünden, während sie noch in ihrer Basis steht und damit die gesamte Festung auslöschen.\n\nNach dem Lesen verbrennen.\n\n-Truppenkommandant Valen\n\nBasislager der Nordwachtexpedition", sourceObjective = "Bringt die Befehle des Stützpunkts zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", progress = "Mehr Gnome?", completion = "Gnomflugmaschinen? Unsere Luftabwehrkanonen funktionieren noch nicht! Wir werden hilflos sein.\n\nIch brauche Zeit für einen Plan... muss nachdenken...\n\nDer Heißluftballon darf mit seiner Ladung nicht in der Feste Krom'gar bleiben. Ich muss ihn an einen anderen Ort bringen. Unsere Pläne zur Vernichtung der Scherwindfeste sind gescheitert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26017] = { id = 26017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köder", description = "Bringt dieses Gerät an Eurem Kopf an und schwimmt dann durch den Tang und die Korallen am Rand der Kluft. Es sollte dort haufenweise kleine Fische geben, die Eure neue Antenne ganz unwiderstehlich finden werden.\n\nWenn wir zur Dämmerbucht zurückkehren, werden wir Berge von Fischen für alle haben!", sourceObjective = "Setzt die Phosphorafedora auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", progress = "Wie viele habt Ihr gefangen?", completion = "Das habt Ihr gut gemacht, {name}! Das habt Ihr richtig gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26018] = { id = 26018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht aus für die Tiefenlichter", description = "Ach, stimmt! Ich sollte ja einen Bericht erstellen! Fast hätte ich es vergessen!\n\nSieht eigentlich nach größtenteils harmlosen Wildtieren aus hier… Bis auf diese verdammten Aale. Und ein paar Murlocs. Ich schätze, der Käpt'n wird sich wohl eher für die Murlocs interessieren.\n\nFordert ein paar von ihnen zum Kampf raus und schaut, was sie so drauf haben. Soweit ich weiß jagen die großen im Tang nach Fischen und die kleinen praktizieren irgendeine Art von Magie oder so... aber mehr weiß ich auch nicht.", sourceObjective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", completion = "<Humphrey hört Euch zu, während Ihr von Euren Kämpfen mit den Tiefenlichtmurlocs berichtet.>\n\nHmm… Klingt nach stinknormalen Murlocs… nur unter Wasser. Das macht den Käpt'n bestimmt froh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26019] = { id = 26019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enormes Aalei", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Humphrey vielleicht daran interessiert sein könnte.>", sourceObjective = "Bringt das enorme Aalei zu Humphrey Grabungslied am Grund der Tiefenlichtkluft in Vashj'ir.", progress = "Was habt Ihr denn da, {name}?", completion = "Waaa… ein Ei? Ein AALEI?\n\n<Sogar kopfüber könnt Ihr sehen, wie es in Humphreys Kopf rattert.>\n\nWir können ganz sicher etwas damit anfangen! Macht Euch bereit, denn jetzt ist es Zeit für ein wenig altmodische Rache à la Grabungslied!", sourceObjectiveStatus = "unverified-source-field" }
quests[26020] = { id = 26020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Bombgutz", description = "Wir müssen uns auf den bevorstehenden Angriff vorbereiten. Unsere Soldaten sollen die Bombe für den Transport bereitmachen. Ihr meldet Euch bei Obersprengenieurin Bombgutz. Sie versucht, unsere Luftabwehrkanonen zu reparieren, bislang jedoch erfolglos. Stellt sicher, dass ihre Motivation für die Reparatur der Kanonen ausreicht, {name}.", sourceObjective = "Meldet Euch bei Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", completion = "Ausreichend motiviert? Was... was soll das heißen? Hört mal zu, Unteroffizier, ich habe einen eingebauten Überlebensmechanismus namens Eigeninteresse. Das heißt, es ist in meinem eigenen Interesse, NICHT ZU STERBEN. Allerdings kann ich die Kanonen nicht ohne die richtigen Materialien reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26021] = { id = 26021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Grabungslied Teil 2: Der Eier-Aal-Trick-Blues", description = "Diese Aale haben meinen Bruder gefressen. Meinen Bruder, {name}! Es ist Zeit, dass ihnen jemand zeigt, wer hier der Boss ist.\n\n<Humphrey nimmt mehrere Dynamitstangen aus seiner Weste und schiebt sie durch die Außenhaut des Eis.>\n\nDiese Großaale im Süden sind zu stark, um alleine gegen sie anzutreten, aber mit diesem Ei sollten wir für Chancengleichheit sorgen können. Legt es in der Nähe dieser Biester ab und dann... Kabumm!\n\nWenn die Bombe den Aal nicht sofort tötet, sollte er zumindest dem Tod nahe sein, sodass Ihr ihm leicht ein Ende setzen könnt.", sourceObjective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", completion = "Oskar ist am Leben? Wartet... Was habt Ihr gesagt? Ihr habt zugelassen, dass er ERNEUT DAVONGETRIEBEN WIRD?!\n\nNun… Ihr habt Euren Teil der Vereinbarung erfüllt und ich weiß zu schätzen, was Ihr getan habt, {name}.\n\nHier… nehmt das. Für mich ist es ohnehin nur Ballast, aber es scheint nicht viel zu nützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26022] = { id = 26022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Blut", description = "Seid bereit, {name}. Ihr werdet für uns das erste Blut auf diesem Land vergießen.\n\nDas Syndikat, so nennen sie sich, besteht aus feigen Menschen, die sogar ihr eigenes Volk verraten. Ihre Isolation macht sie zu einer leichten Beute.\n\nReist nach Norden, tötet alle Syndikatssöldner, die Ihr findet und erobert Nordhof im Namen der Verlassenen. Bringt mir die Blutsteinamulette, die sie tragen, als Zeichen Eurer Eroberung.", sourceObjective = "Erbeutet 10 Blutsteinamulette von Mitgliedern des Syndikats.", progress = "Ich lasse mich nicht von leeren Behauptungen beeindrucken. Könnt Ihr Eure Loyalität beweisen?", completion = "Das ist nur der Auftakt für das Massaker, das wir über dieses Land bringen werden. Alle werden Euren Namen kennen.\n\nDas habt Ihr gut gemacht, {name}. Sieg für Sylvanas!", sourceObjectiveStatus = "unverified-source-field" }
quests[26023] = { id = 26023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Trollbann der Verlassenen", description = "Ich werde Euch eine Geschichte erzählen.\n\nEs gab einmal einen einfältigen Troll namens Zengu. Man befahl ihm, das Schwert Trol'kalar zu finden, die legendäre Klinge der menschlichen Trollbannlinie. Das gelang ihm. Er dachte, seine Aufgabe sei erfüllt und wollte Arathi allein verlassen. Dabei wurde er von den Menschen getötet, die das Schwert einfach wieder an sich nahmen.\n\nWir werden nicht so einfältig sein. Unsere Apotheker haben uns jemanden gebracht, der uns helfen wird, Trol'kalar wiederzubeschaffen: den Prinzen, der es einst besaß.\n\nEr wartet darauf, Euch zu führen, {name}. Sprecht mit ihm.", sourceObjective = "Sprecht mit Galen Trollbann.", completion = "Ja... Einst war ich Prinz des gefallenen Königreichs Stromgarde. Ich wurde getötet von dem, der Trol'kalar suchte.\n\nNun bereue ich mein dummes Leben. Ich diene...nur Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26024] = { id = 26024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Marez Schattenkutte", description = "Es wurde ein Kopfgeld auf Marez Schattenkutte ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.\n\nDas Kopfgeld kann von Hauptmann Nials abgeholt werden.\n\nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie mit Dämonen Umgang hat. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.", sourceObjective = "Bringt Marez' Kopf zu Hauptmann Nials bei der Zuflucht.", progress = "Seid gegrüßt, {class}. Kommt Ihr, um Bericht zu erstatten?", completion = "Ihr habt Marez Schattenkutte erledigt? Gut gemacht, {name}. Wirklich gute Arbeit!\n\nMarez bedrohte unsere Verteidiger von Stromgarde und es wurde gemunkelt, dass sie Abgesandte zwischen dem Syndikat und einer anderen, dunkleren Macht war. Wir sind froh, dass sie nicht länger ihre Kräfte gegen uns einsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26025] = { id = 26025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verräterische Orc", description = "Ich bin mir sicher, dass eine mächtige Hexenmeisterin in den Mauern von Burg Stromgarde haust. Von Zeit zu Zeit beschwört diese Hexenmeisterin mit Hilfe eines arkanen magischen Relikts schreckliche Dämonen in großer Anzahl. Wir müssen die Quelle ihrer Energie entfernen.\n\nFindet und tötet die Hexenmeisterin. Bringt mir das magische Objekt, das sie bei sich trägt. Dann werde ich dafür sorgen, dass es zerstört wird und dass ihre Macht nie wieder unser Land besudelt.", sourceObjective = "Erbeutet Marez Schattenkuttes beschmutzte Blutsteinkugel.", progress = "Das Brennen in meinem Blut... es wird mit jedem Tag stärker. Die Hexenmeisterin muss aufgehalten werden.", completion = "Meine ruhelosen Nächte werden sich in friedlichen Schlaf verwandeln, wenn ich diese Kugel zerstört habe. Danke, {name}. Sie dient als düstere Erinnerung an die schreckliche Macht, die Dämonen über die Orcs ausübten, bevor Höllschrei sie von ihrem Fluch befreite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26026] = { id = 26026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von einer besseren Zukunft", description = "Herr Rosie ist krank, <ehrenwerter/ehrenwerte> {race}. Könnt Ihr ihm helfen? Ihr müsst nur seinen Hut und seine Batterien finden, dann wird es ihm wieder gut gehen. Ich würde sie selbst holen, aber ich kann Herrn Rosie nicht allein lassen!\n\nDie gemeinen Kerle der Venture Company, hinten am Wasserrad, haben seinen Hut gestohlen und seine Batterien sind irgendwo an der Scherwindklippe versteckt. Ihr werdet richtig gut nach ihnen suchen müssen!\n\nWürdet Ihr bitte Herrn Rosies Besitz zurückbringen, damit er den Fieslingen von der Allianz eine Lektion erteilen kann?", sourceObjective = "Bergt die BD-816 Kriegsmaschine, das mechanisierte Feuer, das mechanisierte Eis und die mechanisierte Luft.", progress = "Herr Rosie ist so traurig. Wir müssen ihn wieder fröhlich machen!", completion = "<Clarissa klatscht aufgeregt.>\n\nHerr Rosie, dir geht es gleich wieder gut! Hurra!\n\n<Clarissa setzt die Teile, die Ihr gefunden habt, routiniert in \"Rosie\" ein.>\n\nOh, Herr Rosie! Ich wusste es!", sourceObjectiveStatus = "unverified-source-field" }
quests[26027] = { id = 26027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen", description = "Unser nächster Schlag gegen die Oger wird Euch tiefer in den Osten nach Burg Stromgarde führen. Die Lebenden klammern sich weiter an diese verfallenen Ruinen. Ihre Sentimentalität ist widerwärtig!\n\nFür uns ist Burg Stromgarde nicht mehr als ein verdorbener Bau voller Oger, die auf ihr Ende warten. Reist dorthin. Tötet ihre Schamanen und ihre Lords und sorgt dafür, dass das, was bei den Ogern als Führung durchgeht, vernichtet wird.", sourceObjective = "Tötet 7 Schamanen der Felsfäuste und 3 Lords der Felsfäuste in Stromgarde.", completion = "Alles gesäubert? Gut. Wir werden uns nicht die Mühe machen, Burg Stromgarde zu besetzen. Dieses Drecksloch muss in Staub verwandelt werden.\n\nDas Land würde sich gut für eine neue Unterstadt eignen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26028] = { id = 26028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr Rosies wilder Ritt", description = "Herr Rosie braucht jetzt einen Engel, der ihm bei der Navigation hilft. Werdet Ihr dieser Engel sein, <ehrenwerter/ehrenwerte> {race}? Mit Eurer Hilfe können wir es bis zur Klippe schaffen und viele, viele Allianzkämpfer töten. Was meint Ihr? Och bitte, <edler/edle> {class}! BITTE BITTE BITTE BITTE?\n\nWenn wir genügend Allianzler umbringen, kauft Herr Krom'gar uns allen ein Eis!", sourceObjective = "Tötet 20 Gnomingenieure und 5 Gnomklopfer.", completion = "<Oberanführer Krom'gar hustet.>\n\nIch weiß - vielleicht zum ersten Mal in meinem Leben - nicht, was ich sagen soll.\n\nIch bin mir nicht einmal sicher, wo Clarissa eigentlich her kommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26029] = { id = 26029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die echte Bedrohung", description = "Or'Kalar führt die Oger hier an. Seit Jahren entgeht er seinen Schlächtern. Seine Existenz ist eine Beleidigung der Dunklen Fürstin. Mug'thol, Verräter der Verlassenen, kommandiert ihn aus der Ferne!\n\nWir tolerieren weder Oger noch Verräter im Gebiet der Verlassenen. Bringt mir den Kopf des Ogers. Dann sorge ich dafür, dass er dieses Mal richtig verbrannt wird.", sourceObjective = "Tötet Or'Kalar und nehmt seinen Kopf.", progress = "Fasst Euch kurz.", completion = "Dieses Schicksal blüht allen, die uns im Weg sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26030] = { id = 26030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Strom", description = "In grauer Vorzeit führte Lord Ignaeus von Strom, den sie Trollbann nannten, die erste menschliche Zivilisation von Arathor in den Krieg gegen die Trolle. Seine Klinge hieß Trol’kalar – was in ihrer alten Sprache Trolltöter heißt.\n\nIch war einer der letzten seines Geblüts und hatte die Aufgabe, Trol’kalar zu hüten... eine Aufgabe, bei der ich versagt habe. Aber jetzt werden wir die Klinge für meinen neuen Meister erneut in unseren Besitz bringen.\n\nDas Schwert wird von drei Siegelzeichen beschützt. Der erste befindet sich in den Händen der Verräter des Syndikats, die in den Ruinen von Stromgarde herumlungern. Tötet sie und bringt das Siegelzeichen zu mir.", sourceObjective = "Erhaltet das Siegelzeichen von Strom von den Mitgliedern des Syndikats in Burg Stromgarde.", progress = "Nur die Mitglieder des Syndikats innerhalb Stormgardes werden das Siegelzeichen bei sich haben. Außerhalb der Festung Blut zu vergießen ist Zeitverschwendung.", completion = "Ich habe das Syndikat zu Lebzeiten genauso sehr gehasst, wie ich sie im Tode hasse. Das Siegelzeichen wiederzusehen ist ein kleiner Trost.\n\nAber wir haben noch viel mehr Arbeit vor uns... für Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26031] = { id = 26031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen des Thoradin", description = "Als ich noch lebte, zerbrach ich das Siegelzeichen des Thoradin in fünf Teile, um es zu schützen. Ich gab sie meinen loyalsten Männern. Das schlug ebenfalls fehl, aber mein Nachfolger wird dasselbe getan haben.\n\nDie Verteidiger von Burg Stromgarde tragen die Teile des Siegelzeichens wieder bei sich. Tötet sie und bringt mir die Scherben; ich werde sie zusammensetzen.", sourceObjective = "Erbeutet 5 Siegelzeichenfragmente von Vollstreckern von Stromgarde in Burg Stromgarde.", progress = "Nur mit allen fünf Teilen kann das Siegelzeichen wiederhergestellt werden...", completion = "Thoradin war der Gründer von Arathor. Ich vereine diese Fragmente, so wie er einst die verstreuten Stämme der Menschen vereinte und ihre erste große Nation erschuf.\n\nDoch dieses Gefasel interessiert Euch sicherlich nicht. Vergebt mir. Alte Erinnerungen lassen sich nur schwer begraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26032] = { id = 26032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Arathor", description = "Ich habe dieses Siegelzeichen Leutnant Heldenruf, dem Anführer meiner Kavallerie, anvertraut. Er hätte beinahe sein Leben verloren, als es gestohlen wurde.\n\nDieses Mal wird er wohl weniger Glück haben. Heldenruf patrouilliert zwischen Burg Stromgarde und der Zuflucht. Findet ihn und nehmt ihm noch einmal das Siegelzeichen ab.", sourceObjective = "Nehmt Leutnant Heldenruf das Siegelzeichen von Arathor ab.", progress = "Habt Ihr das Siegelzeichen?", completion = "Heldenruf war mir im Leben treu ergeben. Seinen Tod ertrage ich nur schwer.\n\nDoch das muss ich. Ich bin ein Verlassener. Meine alte Existenz hat keine Bedeutung.\n\nWir haben die Siegelzeichen; Trol'kalar erwartet uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26033] = { id = 26033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "Ich habe das letzte Siegelzeichen... und mit ihm vereine ich die vier zum Siegelzeichen von Trollbann, dem Schlüssel zur Gruft. Wir sind bereit.\n\nTrol'kalar wurde gemeinsam mit den Überresten seines Herrn eingeschlossen. Es liegt in Trollbanns Grabmal in den Katakomben von Burg Stromgarde. Es wird schwer bewacht sein... aber dass ich vor Euch stehe, beweist, dass die Vollstrecker besiegt werden können.\n\nBetretet das Grabmal, bergt Trol'kalar und bringt es her.", sourceObjective = "Bergt Trol'kalar aus Trollbanns Grabmal in Burg Stromgarde.", progress = "Habt Ihr Trol'kalar?", completion = "Trol'kalar, die Klinge meines Vaters... es erscheint mir, als hätte ich sie vor einer Ewigkeit zuletzt gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26034] = { id = 26034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwielichtzerstörer", description = "Dies war kein leichtfertiger Angriff, sondern vielmehr ein sorgsam inszenierter Schlag gegen das Herz des roten Drachenschwarms.\n\nZarithrian, der sich auf dem Felsvorsprung dort drüben befindet, überwacht den Angriff, doch ist der wahre Anführer ein dreister und mächtiger Zwielichtdrache namens Halion. Seit Dargonax ist kein ausgewachsenes Exemplar der Brut aus Sinestras verdorbenen Experimenten mehr gesichtet worden.\n\nTötet ihn, {name}. Sobald es Euch gelungen ist, diese Invasion zurückzudrängen, meldet Ihr Euch bei Krasus und berichtet ihm, was Ihr hier gesehen habt.", sourceObjective = "Besiegt Halion und drängt die Invasion des Rubinsanktums zurück.", completion = "<Krasus hört konzentriert zu, während Ihr von Eurem Kampf gegen Halion berichtet. Seine Augen weiten sich, als Ihr Todesschwinge erwähnt.>\n\nWir schulden Euch großen Dank dafür, dass Ihr die Eindringlinge aus dem Sanktum getrieben habt. Doch die Neuigkeiten über den Zerstörer sind über alle Maße beunruhigend. Es gibt vieles, was ich mit den anderen Mitgliedern des Wyrmruhpakts besprechen muss.\n\nNehmt dies als Zeichen meiner Anerkennung, während Ihr Euch gegen den aufziehenden Sturm wappnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26035] = { id = 26035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Gewicht in Gold", description = "Erzmagier Malin hat mich hierher geschickt, um Reagenzien für ihn zu sammeln. Ich habe mich gefragt, wie ich ihm die Gegenstände besorgen soll, aber nun, da Ihr hier seid, könnte sich dieses Problem erledigt haben.\n\nIch benötige Hauer der Bleichborken und Medizinbeutel der Bleichborken.\n\nWürdet Ihr sie für mich holen? Die Bleichborken leben südöstlich von Arathi.", sourceObjective = "Erbeutet 10 Hauer der Bleichborken und 4 Medizinbeutel der Bleichborken von Trollen der Bleichborken.", progress = "Wie läuft es bislang?", completion = "Nicht schlecht. Da Ihr Euren Kopf anscheinend wirklich zum Denken benutzt, hoffe ich, dass Ihr uns in einer dringenderen Angelegenheit behilflich sein könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26036] = { id = 26036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberstab gegen Faust", description = "He, {name}. Tut mir leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.\n\nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.\n\nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandolübergang. Findet diesen Oger und holt den Zauberstab.\n\nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.", sourceObjective = "Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.", progress = "Unser Ziel ist der Zauberstab, {name}. Konzentriert Euch vorerst nur darauf.", completion = "Genial, {name}. Einen Gegenstand haben wir, fehlen nur noch drei, laut meiner Liste. Die anderen drei Gegenstände befinden sich alle in Stromgarde.\n\nRuht Euch eine Weile aus, damit Ihr wieder zu Kräften kommt - die nächste Phase meines Plans erfordert etwas mehr Zeit und Mühe. Kommt wieder zu mir, wenn Ihr etwas Warmes im Bauch und Euch ausgeruht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26037] = { id = 26037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trelanes Verteidigung", description = "Na, erholt?\n\nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen Euch gegen die Verteidigungsanlagen des Turms einsetzen. Dazu brauchen wir ein paar Edelsteine, an denen der Schamane der Felsfäuste Gefallen gefunden hat. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.\n\nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann.", sourceObjective = "Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten in Burg Stromgarde.", progress = "Da seid Ihr ja wieder, {name}. Habt Ihr schon einen azurblauen Achat gefunden?", completion = "Ihr erstaunt mich, {name}. Nochmals, gut gemacht.\n\nGebt mir einen Moment Zeit, um den richtigen Zauber zu wirken, dann ist alles bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26038] = { id = 26038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm", description = "Hier ist das, wonach Ihr suchen müsst: Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat.\n\nAlle drei liegen in Kisten innerhalb des Turms. Die Kisten solltet Ihr allein problemlos öffnen können, passt nur auf die Oger auf.\n\nHaltet Eure Waffen bereit. Wenn die Oger herausfinden, dass Ihr dort seid und sie bestehlen wollt, dann werden sie nicht zimperlich mit Euch umgehen.\n\nSeid vorsichtig und viel Glück.", sourceObjective = "Findet Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt sie Skuerto in der Zuflucht.", progress = "Wenn Euch das gelingt, wird Malin sehr zufrieden mit Euch sein.", completion = "Malin hat genau die richtige Person um Hilfe gebeten, {name}. Das war tolle Arbeit!\n\nEs wird ihn freuen, dass unsere Mission ein so großartiger Erfolg war.", sourceObjectiveStatus = "unverified-source-field" }
quests[26039] = { id = 26039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Prinzessin", description = "Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.\n\nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.\n\nIch flehe Euch an, {name}, helft mir!", sourceObjective = "Sammelt 12 Körner von Myzrael von Kobolden der Trockenstoppel.", progress = "Diese Gruppe von Splittern sieht den Splittern von Myzrael sehr ähnlich. Aber durch sie pulsiert kein Gefühl der Sicherheit.", completion = "Ah! Ihr habt diese Splitter aktiviert! Ich fühle mich schon mehr wie ich selbst!\n\nAber weh mir, ich bin immer noch weit davon entfernt, frei zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[26040] = { id = 26040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Macht den Algen", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, {race}. Bringt mir etwas davon!", sourceObjective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", progress = "Konntet Ihr welche von diesen Algen für mich finden, {race}?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26041] = { id = 26041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Bindung", description = "Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.\n\nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.\n\nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.", sourceObjective = "Holt den brennenden Schlüssel, den schäumenden Schlüssel und den donnernden Schlüssel vom Stein der Westlichen Bindung, dem Stein der Östlichen Bindung und dem Stein der Äußeren Bindung.", progress = "Dies ist der Stein der Inneren Bindung. Er ist der stärkste der Bindungssteine und muss erst aufgeschlossen werden, damit die anderen sich öffnen.", completion = "<Myzrael spricht durch den Stein.>\n\nIhr habt es geschafft! Ihr habt die Steine der Bindung geöffnet! Ich fühle, wie meine Fesseln sich lösen und die Freiheit immer näher rückt.\n\nIhr seid ein edelmütiger {class}, {name}. Mein Retter!", sourceObjectiveStatus = "unverified-source-field" }
quests[26042] = { id = 26042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hauptstein zerbrechen", description = "Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.\n\nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.\n\n{name}, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!", sourceObjective = "Beschafft die Rute der Ordnung von Fozruk.", progress = "Der Hauptstein ist mit einer enormen geomantischen Energie aufgeladen.", completion = "Ihr platziert die Rute im Hauptstein. Und fühlt unter Euch eine Erschütterung...", sourceObjectiveStatus = "unverified-source-field" }
quests[26043] = { id = 26043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HÜTET EUCH VOR FELSKIEFER!", description = "Auf Befehl von Oberanführer Krom'gar ist das Betreten des Felskesselsees VERBOTEN!\n\nDie wilde Bestie, die Felskiefer genannt wird, hat den See in eine Todesfalle verwandelt. Solltet Ihr Felskiefer beseitigen, nehmt seinen riesigen Zahn als Trophäe und bringt ihn zur Herrin der Spione Anara. Sie wird Euch belohnen.", sourceObjective = "Tötet Felskiefer und nehmt Euch Felskiefers riesigen Zahn.", progress = "Was wünscht Ihr?", completion = "Ein Beweis für die Macht der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26044] = { id = 26044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind die Teile?", description = "Ich warte seit Tagen auf Teile für diese Waffen! Ich habe einen meiner besten Sprengenieure und zwei Dutzend Minenarbeiter vor fünf Tagen in die Ausufernden Tiefen geschickt, um die Teile zu besorgen. Als ich drei Tage später noch nichts von ihnen gehört hatte, begann ich mir Sorgen zu machen. Der Oberanführer schickte zwei seiner besten Orcs hinterher. Seitdem haben wir nichts gehört...\n\nBegebt Euch in die Ausufernden Tiefen, unmittelbar unter dieser Festung, und findet heraus, was los ist! Ich brauche die Teile!", sourceObjective = "Sprecht mit Unteroffizier Dontrag in den Ausufernden Tiefen im Steinkrallengebirge.", completion = "Äh... Na ja, das ist ganz einfach... IN DIESER HÖHLE WIMMELT ES VON SEELENLOSEN MORDMASCHINEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[26045] = { id = 26045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Teile sind schon hier...", description = "Mein Dilemma sieht so aus: Ich habe zwei Möglichkeiten. Entweder lasse ich mich wie alle anderen hier unten umbringen oder ich werde in der Feste Krom'gar umgebracht, wenn Krom'gar erfährt, dass wir die Mine verloren haben. Ich wähle die dritte Möglichkeit: nichts tun. Klappt bisher ganz gut.\n\nIhr braucht Teile? In der Mine liegt eine Menge Schrott herum. Ihr müsst ihn nur holen.\n\nViel Glück! Wenn Ihr diese Teile holt, können wir uns vielleicht wieder in der Feste Krom'gar blicken lassen.", sourceObjective = "Sammelt 10 Ersatzteile.", progress = "Wie läuft die Jagd?", completion = "Ich fasse es nicht! Ihr habt die Teile bekommen und seid nicht gestorben. Wieso seid Ihr nur Unteroffizier?", sourceObjectiveStatus = "unverified-source-field" }
quests[26046] = { id = 26046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was immer wir tun...", description = "Dontrag kann das besser erklären als ich. Was auch immer wir tun, es ist das Falsche. Wir können hier unten nichts tun wegen all der Dinge, die uns umbringen wollen und können nicht zur Basis zurückkehren wegen all der Dinge, die uns umbringen wollen - verstanden?\n\nVielleicht können wir dieses Problem ja gemeinsam lösen. Beseitigt Ihr doch schon mal ein paar dieser Elementare, die anscheinend alles in der Mine umgebracht haben, einverstanden?", sourceObjective = "Tötet 12 tobende Erdelementare.", completion = "Holt die Teile, tötet die Elementare und rettet die Peons... Wenn wir das hinkriegen, ist uns eine Beförderung sicher!", sourceObjectiveStatus = "unverified-source-field" }
quests[26047] = { id = 26047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deshalb nennt man sie Peons...", description = "Die beiden sind NUTZLOS! Als sie eintrafen, dachte ich, wir wären gerettet. Aber nein! Stattdessen warfen Dontrag und Utvoch einen Blick in die Mine und dachten sich einen idiotischen Plan aus, der vor allem aus Herumstehen besteht... wahrscheinlich, bis wir alle tot sind. \n\nIhr seht nicht ganz so nutzlos aus. Wollt Ihr uns helfen, <Freund/Freundin>? In den Ausufernden Tiefen verstecken sich Dutzende von Peons, die nur noch Angst in der Birne haben. Findet sie und holt sie raus!", sourceObjective = "Rettet 10 verängstigte Peons.", progress = "Habt Ihr meine Peons gefunden?", completion = "Ich wusste es! Ihr seid ein Held! Wenn ich etwas zu sagen hätte, würdet Ihr zum Legionär befördert!", sourceObjectiveStatus = "unverified-source-field" }
quests[26048] = { id = 26048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile hier herauf!", description = "Puh, das war hart. Ich dachte, wir würden es nicht schaffen, {name}. Am besten bringen wir diese Teile zurück zu Obersprengenieurin Bombgutz. Ich glaube, ich höre draußen schon das Summen der Gnomflugmaschinen. Wir haben keine Zeit zu verlieren!", sourceObjective = "Bringt die Kiste mit Ersatzteilen zu Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", progress = "Habt Ihr meine Teile?", completion = "Gerade noch rechtzeitig! Die Flugmaschinen sammeln sich bereits. Der Angriff steht unmittelbar bevor!", sourceObjectiveStatus = "unverified-source-field" }
quests[26049] = { id = 26049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die entfesselte Prinzessin", description = "Myzrael ist keine unschuldige Prinzessin. Sie ist unglaublich gefährlich. Die Riesen hatten sie aus gutem Grund dort unten angekettet. Man hat Euch leider betrogen.\n\nGerrig sagt, dass Ihr sie bei den Splittern von Myzrael, dort, wo Ihr zuerst mit ihr gesprochen habt, beschwören müsst. Besiegt sie und nehmt Euch ihre geisterhaften Fesseln. Bindet sie damit an die Splitter.\n\nIhr werdet diese Schriftrolle brauchen. Geht sorgsam mit ihr um; ich habe ein paar Zähne riskiert, um sie zu bekommen. Viel Glück, {name}.", sourceObjective = "Beschwört und besiegt Myzrael an den Splittern von Myzrael.", progress = "Die Splitter von Myzrael sind nun seltsam still.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, erschallt von tief unten ein unmenschliches Heulen. Auf den Schrei folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht länger Gefühle der Wärme und Sicherheit hervor, wie sie es zuvor taten. Jetzt sind sie erfüllt von einer feindseligen Aura... als ob das Ding unter ihnen der Außenwelt nicht wohlgesinnt wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[26050] = { id = 26050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtbrille", description = "Als frisch gebackene Schwarzmeerräuber ist es unsere Aufgabe, dem ehrenwerten O'Breen bei der Suche nach dem verlorenen Elfenschatz zu helfen.\n\nEs ist fast unmöglich, die Edelsteine ohne Hilfsmittel im dunklen Wasser zu finden. Der Doktor hat für diesen Fall eine Brille konstruiert. Die Brille muss mit der Energie aus dem verzauberten Stein in der Höhle auf dem Hügel aufgeladen werden.\n\nDoch die Höhle ist verflucht! Man wird uns angreifen, wenn wir näher kommen. Verteidigt mich, dann kann ich die Energie aus dem Stein in die Brille übertragen.", sourceObjective = "Begleitet Professor Prasseltrop zur Höhle und zurück.", completion = "Die Brille funktioniert nun perfekt! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26051] = { id = 26051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.\n\nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!\n\nAlso nehmt Euch die Edelsteinjagdschutzbrille, {name}, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.\n\nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.", sourceObjective = "Doktor Drechselknacks in der Faldirbucht will, dass Ihr 10 Elfenedelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.", progress = "Wie lief es mit der Schutzbrille? Hat alles korrekt funktioniert? Änderungen können durchgeführt werden, falls es notwendig ist.\n\nOh, und ich brauche die Schutzbrille zurück, wenn Ihr fertig seid. Ich bin sicher, Kapitän O'Breen wird sie später für verschiedene Dinge gut gebrauchen können.", completion = "Absolut superb, {name}. Der Kapitän wird sehr erfreut sein! Und wartet nur, bis Flottenmeister Seehorn davon erfährt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26052] = { id = 26052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Wank", description = "Lassen wir Kapitän O'Breen nicht warten. Er wird die Edelsteine selbst sehen wollen. Deshalb sind wir schließlich hier!\n\nUnd nach ein paar Wochen in der Gesellschaft dieser Piraten, haben der Professor und ich erkannt, dass es äußerst gesundheitsschädlich ist, sich mit ihren Schätzen erwischen zu lassen.\n\nHier, {name}, bringt sie zu O'Breen.", sourceObjective = "Bringt die Elfenedelsteine zu Kapitän O'Breen in der Faldirbucht im Arathihochland.", progress = "Ahoi, {class}. Was führt Euch auf die Brücke?", completion = "Dann haben sich die kleinen Gnome tatsächlich als nützlich erwiesen? Ich wusste doch, dass wir die Fersenbeißer nicht grundlos mitschleppen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26053] = { id = 26053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung des Hochlands", description = "Wir werden keine Bedrohung übersehen. Um dieses Land zu sichern und der Dunklen Fürstin zu unterwerfen, müssen wir alles, was auf ihm lebt, herausreißen, Stück für Stück, Meter für Meter.\n\nIm Nordosten, weniger als einen Steinwurf von diesem Lager entfernt, befindet sich ein Ogerhügel. Die Oger der Felsfäuste, die dort leben, müssen ausgelöscht werden, {class}.\n\nSie stehen uns im Weg. Zögert nicht und seid nicht gnädig.", sourceObjective = "Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste.", completion = "Hervorragend. Der Marsch der Verlassenen geht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[26055] = { id = 26055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ertrunkene Trauer", description = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.\n\nDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.\n\nO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!\n\nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.\n\nIch will diese Biester tot sehen.", sourceObjective = "Kapitän Stahlmagen in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberinnen der Säbelflossen tötet.", completion = "Ihr habt da draußen gute Arbeit geleistet, {name}.\n\nDieser Abschaum hat bekommen, was er verdient. Auch wenn nichts auf der Welt mir jemals mein Schiff oder meine Crew zurückbringen wird, der Tod der Naga tröstet mich ein wenig.", sourceObjectiveStatus = "unverified-source-field" }
quests[26056] = { id = 26056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wellensprecherin", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", sourceObjective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", completion = "Bin ich froh, dass Ihr hier seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[26057] = { id = 26057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wellensprecherin", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", sourceObjective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", completion = "Bin ich froh, dass Ihr hier seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[26058] = { id = 26058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Feste Krom'gar", description = "Wir haben keine Zeit mehr. Sie kommen! Übernehmt die Kontrolle über eine schwere Kanone und holt die Gnome vom Himmel! Die Bombe wird explodieren, wenn sie zu oft getroffen wird, und wir mit ihr!\n\nVerteidigt die Basis, {name}! Ihr seid unsere einzige Hoffnung!\n\nMeldet Euch bei Oberanführer Krom'gar, sollten wir das wider Erwarten überleben.", sourceObjective = "Zerstört 15 gnomische Flugmaschinen oder Gnomenbomber und 25 Gnomenschwadronskommandanten.", progress = "Unsere Feinde umzingeln uns!", completion = "Ich habe noch nie eine so mutige Tat gesehen. Ihr habt die Basis gerettet, Unteroffizier - oder sollte ich besser Legionär sagen! Lok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26059] = { id = 26059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen und Ohren: Malaka'jin", description = "Ehrenwacht ist gefallen. Der Griff, in dem die Horde das Brachland hielt, wurde aufgesprengt, ebenso wie das Land. Nun erhalte ich Berichte, in denen es heißt, ein gemeinsamer Angriff der Allianz und der Grimmtotem würde Malaka'jin bedrohen. Wenn Malaka'jin fällt, fällt auch das halbe Steinkrallengebirge!\n\nIhr habt Euch als ein fähiger Soldat der Horde erwiesen. Wollt Ihr meine Augen und Ohren in Malaka'jin sein? Hexendoktor Jin'Zil erwartet Euch.\n\nMalaka'jin befindet sich weit im Süden.", sourceObjective = "Meldet Euch bei Hexendoktor Jin'Zil in Malaka'jin im Steinkrallengebirge", completion = "Wie ich sehe, schickt Krom'gar den Besten!\n\nGut, wir haben viel zu tun. Die dreckige Allianz hat ein Abkommen mit den Grimmtotem unterzeichnet. Jetzt müssen wir die Angriffe beider Streitkräfte abwehren.\n\nWir haben nicht genügend Soldaten im Hochwipfeltal und können es nicht mehr lange gegen die konzentrierten Angriffe unserer Feinde verteidigen. Wir haben nur noch eine Hoffnung: VOODOO!", sourceObjectiveStatus = "unverified-source-field" }
quests[26060] = { id = 26060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Stürmerherz", description = "Mit Voodoo könnte es unseren Truppen gelingen, den Angriff der Grimmtotem zurückzuschlagen. Allerdings brauche ich verschiedene Zutaten, um diese schwarze Magie zu wirken.\n\nDie erste Zutat auf meiner Liste ist das Herz eines Klippenstürmers. Die Bestien sind fast ausgerottet, aber in dieser Gegend gibt es noch ein paar. Findet eine und erbeutet ihr klopfendes Herz!", sourceObjective = "Besorgt ein Klippenstürmerherz.", progress = "Ich brauche das Klippenstürmerherz.", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26061] = { id = 26061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Widderhörner", description = "Um den Voodoo zu wirken, brauche ich besondere Reagenzien. Bringt mir Hörner der Steinkrallenwidder in dieser Gegend, {name}! Ohne die Hörner sind wir erledigt!", sourceObjective = "Besorgt 6 Hörner eines Steinkrallenwidders.", progress = "Ich brauche Hörner von Steinkrallenwiddern!", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26062] = { id = 26062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Resonitkristall", description = "Die letzte Zutat für das Voodooritual ist eine spezielle Kristallart namens Resonit. Man findet sie nur in den Steinschlaghöhlen westlich von hier. Passt auf die Kobolde auf! Sie beschützen das Resonit mit ihrem Leben!", sourceObjective = "Besorgt 8 Resonitkristalle.", progress = "Ich brauche die Resonitkristalle!", completion = "Endlich! Nun kann ich das Amulett mit der Voodooverzauberung erschaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26063] = { id = 26063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin und ihr Hofstaat", description = "<Scholli grunzt.>\n\nHrmph.\n\nDinge brechen auseinander. Scholli unglücklich. Jetzt Schollis Gefährtin umgebracht von Spinnen in Weberkuhle. Scholli will Rache!\n\nHelft Scholli? Tötet Königin Silith und ihre kleinen Spinnlinge? Für Scholli? Für Schollis Gefährtin!\n\nWeberpass ist im Nordwesten, den Weg hoch. Geht!", sourceObjective = "Tötet Königin Silith und 10 beliebige Spinnen in der Weberkuhle.", progress = "Habt Ihr Silith für Scholli getötet?", completion = "Scholli immer noch nicht sehr glücklich, aber Scholli wird Euch für Tat belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26064] = { id = 26064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Kampf auf leeren Magen", description = "Die Truppen sind hungrig, {name}. Seit unsere Nachschublinien abgeschnitten wurden, gehen uns die Vorräte aus. Ich kann den Soldaten ein Festmahl zubereiten, wenn Ihr mir einige Zutaten besorgt.\n\nBegebt Euch in die Wälder westlich von hier und sucht nach Nestern der Kalimdoradler. Stehlt die Eier aus den Nestern und bringt sie mir.", sourceObjective = "Beschafft 8 Eier des Kalimdoradlers.", progress = "Ich brauche Eier!", completion = "Danke, {name}. Diese Eier reichen für eine Woche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26065] = { id = 26065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Willi", description = "Diese Tentakelschrecken haben das arme Tier eingefangen. Bitte, {name}, könnt Ihr es nicht retten, indem Ihr diese Abscheulichkeiten tötet?\n\nWürdet Ihr Willi seine Freiheit zurückgeben?\n\nHier, nehmt mein Totem und stellt es in der Nähe der Tentakel auf. Die Kälte, die es verströmt, bringt diese Monster zum Schrumpfen, sodass Ihr sie einfach besiegen könnt.", sourceObjective = "Tötet alle Tentakelschrecken, um Willi zu befreien.", completion = "Danke, {name}.\n\nDiese alptraumhaften Gestalten aus der Tiefe geben mir zu denken. Ich fürchte, dass unsere Anstrengungen vollkommen umsonst sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26066] = { id = 26066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung...", description = "Anscheinend haben wir fast keine großen, dummen Orcs mehr, die wir dem Feind entgegenschicken können. Das ist ein Problem. Zum Glück habe ich möglicherweise eine Lösung.\n\nNehmt diese Peitsche und geht nach Westen zur Steinschlaghöhle. In der Höhle werdet ihr ein schmutziges Koboldnest finden. Bändigt die Bestien mit meiner Peitsche. Wenn sie erst einmal gebändigt sind, werden sie tun, was wir wollen.\n\nKehrt zurück, wenn ihr eine anständig große Koboldarmee zusammen habt.", sourceObjective = "Bändigt 6 Steinschlagkobolde mit der Peitsche von Unterwerfer Devo.", completion = "In einer Krise wie dieser, könnte eine verzweifelte Tat uns den Sieg bringen. Vielleicht gewinnen wir, wenn wir einen Schwarm Kobolde auf den Feind hetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26067] = { id = 26067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zils Segen", description = "Ah, es ist vollbracht! Nun müssen wir ihn ausprobieren.\n\nReist zum größten Konfliktherd im Hochwipfeltal und setzt meinen Voodoostecken bei den Marodeuren von Krom'gar ein, die gegen die Grimmtotem kämpfen. Dank meiner Voodoomagie sollten sie ihre Schlagkraft zurückerhalten und unsere Feinde vernichten!\n\nGeht jetzt, {name}!", sourceObjective = "Benutzt Jin'Zil's Voodoostecken, um 12 Marodeure von Krom'gar mit Voodoo zu erfüllen.", completion = "Endlich ein Sieg! Allerdings wird er ohne eine stabile Nachschublinie nicht von langer Dauer sein. Genießt ihn so lange, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26068] = { id = 26068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut der Kobolde!", description = "Jetzt kommandieren wir die Koboldarmeen des Steinkrallengebirges! Klingt fast schon beeindruckend. Fast.\n\n<Devo seufzt.>\n\nDas Basislager der Allianz, nördlich von hier, wird streng bewacht. Es ist fast uneinnehmbar. Nur nordöstlich von hier, an der Grabstätte, gibt es einen Eingang. Nehmt das Koboldkriegshorn und brecht zur Grabstätte auf. Betretet sie von Osten, {name}! Von dort aus reist Ihr nach Westen, bis Ihr den Punkt erreicht, den ich auf Eurer Karte markiert habe. Benutzt das Horn und bringt die Wut der Kobolde über die Allianz!", sourceObjective = "Benutzt das Koboldkriegshorn nahe des Banners der Horde an der Grabstätte, um die Koboldarmee loszulassen!", progress = "Auf mein Zeichen! Entfesselt die Koboldhölle!", completion = "<Devo lacht.>\n\nFaszinierende Geschichte, Freund. Unsere neuen Koboldverbündeten scheinen doch ganz nützlich zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26069] = { id = 26069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nura Pfadfinder", description = "Das Südliche Brachland wird von der Allianz angegriffen. Die Tauren bitten um Hilfe. Wir können sie nicht abweisen. Alle gesunden Soldaten der Horde sollten ihnen helfen.\n\nWenn Ihr sie unterstützen wollt, dann nehmt den Weg zum Höhenpfad. Ihr findet ihn im Dorf. Sucht nach Nura Pfadfinder.", sourceObjective = "Meldet Euch bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland.", completion = "Die Lage ist ernst, {race}. Wir brauchen all die Hilfe, die wir kriegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26070] = { id = 26070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterung der Entweihten", description = "Unsere Freunde des Irdenen Rings hier haben uns gefragt, ob wir ihnen nicht zur Hand gehen könnten. Wie es scheint treiben im Brühgraben ein paar Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nKönnt Ihr Euch für mich darum kümmern?", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", completion = "Das soll mir reichen. Hier ist Euer Anteil, wie versprochen.\n\nAber werdet nicht selbstgefällig, {name}. Der schwere Teil kommt erst noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26071] = { id = 26071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterung der Entweihten", description = "Diese Leute vom Irdenen Ring wollen, dass wir das Töten für sie übernehmen. Im Brühgraben treiben einige Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nSchwimmt mal runter und kümmert Euch darum.", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", completion = "Gut gemacht.\n\nAber bildet Euch nicht zu viel darauf ein, {name}. Der schwere Teil kommt erst noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26072] = { id = 26072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Totem", description = "Ihr müsst mein Totem nach unten in den Brühgraben bringen. Benutzt es, um die Energien der Gesichtslosen einzufangen, wenn sie sterben. Das Totem wird sie davon abhalten, dahin zurückzukehren, wo sie herkamen.\n\nWenn das Totem ganz gefüllt ist, bringt es zu mir zurück. Wir werden es verwenden, um ihren Anführer aus der tiefsten Tiefe hervorzulocken.", sourceObjective = "Tötet 5 gesichtslose Entweiher, während sie sich in der Reichweite des Totems der Einsperrung befinden.", completion = "Ja, {race}. Könnt Ihr spüren, wie sie mit aller Macht versuchen auszubrechen und uns zu vernichten?\n\nDas ist gut! Sie sind der perfekte Köder für ihren Anführer.", sourceObjectiveStatus = "unverified-source-field" }
quests[26073] = { id = 26073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Süden nichts Neues", description = "Kehrt jetzt zu Oberanführer Krom'gar zurück, {name}. Teilt ihm unsere Lage mit und berichtet, was Ihr getan habt, um Malaka'jin vor dem Fall zu bewahren.\n\nWir danken Euch für alles, was Ihr getan habt. Vielleicht werdet Ihr eines Tages Eure eigene Region kommandieren.", sourceObjective = "Meldet Euch bei Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", completion = "Lok'tar ogar! Ihr seid die Verkörperung all dessen, was einen Soldaten der Horde ausmacht, {name}. Hätten wir doch nur mehr wie Euch, dann wäre der Krieg bereits vorbei und Kalimdor würde der Horde gehören - UNANGEFOCHTEN!!\n\nErhebt Euch als ein Champion von Krom'gar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26074] = { id = 26074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anfang vom Ende", description = "Champion, wir haben ein neues Ziel anvisiert. Unsere Späher im Kriegsnarbental melden, dass die Nachtelfen an ihrer eigenen Massenvernichtungswaffe arbeiten und sie in einem uralten Baum verbergen. Sie werden nie die Gelegenheit bekommen, sie gegen uns einzusetzen.\n\nIhr werdet die Bombe zum Auftanken zu den Schlickwerken begleiten und danach zum Klippenläuferposten. Von dort aus werden wir die Bombe zünden und all unsere Feinde vernichten.\n\nGeht jetzt, {name}. Meldet Euch bei Jibbly Rakit, wenn ihr an den Schlickwerken eintrefft.", sourceObjective = "Fahrt im Heißluftballon von Krom'gar zu den Schlickwerken im Steinkrallengebirge.", completion = "Krom'gar hat seinen Champion geschickt! Ihr müsst Euch keine Sorgen machen, Champion. Wir tanken den Ballon rasch wieder auf. Wollt Ihr uns in der Zwischenzeit ein wenig helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26075] = { id = 26075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Probleme", description = "Wir haben ein kleines Problem...\n\n<Jibbly zeigt auf die großen Kothaufen, die überall in der Basis liegen.>\n\nWir haben die Schlickwerke in der Nähe eines Wyvernhabitats errichtet. Die Risszeichnungen der Schlickwerke wurden mit großer Sorgfalt erstellt, damit die Wyvernhabitate nicht gestört werden. Anscheinend verehren die Tauren und Orcs die Bestien. Wisst Ihr, was ich verehren würde? Einen Tag ohne Koteinschläge!\n\nGanz im Vertrauen, die Wyvern müssen sterben!", sourceObjective = "Tötet 6 beliebige Prachtschwingenwyvern.", completion = "Hoffentlich sind Euch keine entgangen. Ich halte das nicht mehr länger aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[26076] = { id = 26076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spionageplage", description = "Wir haben noch ein Problem, {name}. Es wimmelt hier von Allianzspionen! Ihr habt keine gesehen? Weil sie unsichtbar sind! Getarnt! Ich habe eine Lösung, aber dafür brauche ich jemanden, der die Kraft und das Geschick hat, meinen Plan umzusetzen.\n\nBenutzt diese Gasbombe, dann werdet Ihr die getarnten Spione sehen können. Schickt sie zu ihrem Schöpfer, wenn Ihr sie enttarnt habt.\n\nIhr erkennt einen getarnten Spion an dem Effekt, den sie auf die Luft haben. Seht genau hin!", sourceObjective = "Tötet 8 Allianzspione. Enttarnt die Spione mit Jibblys Gasbombe!", progress = "Habt Ihr die Spionageplage gestoppt?", completion = "Alle dachten, ich spinne. Aber ich wusste, dass es hier überall Spione gibt. Und Kacke.", sourceObjectiveStatus = "unverified-source-field" }
quests[26077] = { id = 26077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Lieferung", description = "Oberanführer Krom'gar hat einen Befehl aus der Basis übermittelt. Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten. Der Plan sieht vor, von dort aus mit der Bombe die Allianz im Kriegsnarbental zu vernichten.\n\nMacht Euch auf, {name}. Man sollte Krom'gar nicht warten lassen.\n\nSprecht mit General Grebo, wenn Ihr Euer Ziel erreicht habt. Er wird Euch über Eure nächste Mission informieren.", sourceObjective = "Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten im Steinkrallengebirge.", completion = "Häuptling Klippenläufer und seine Tauren wollen die Horde verraten! Sie behaupten, dass der uralte Baum im Kriegsnarbental nur eine Druidenschule ist. Sie verstehen nicht, dass Kriegszeiten verzweifelte Maßnahmen verlangen. Meine Späher haben mir versichert, dass die Nachtelfen eine äußerst mächtige Waffe in diesem Baum verbergen. Wir müssen damit aufräumen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26078] = { id = 26078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht die Feuer", description = "Der Angriff der Dunkeleisenzwerge hat uns überrascht. Ihre Saboteure haben viele unserer Flugzeuge, Dampfpanzer und Vorräte beschädigt. Wir konnten nur noch ein paar Bomber rechtzeitig starten.\n\nJeder Techniker, jeder Rekrut und jede Wache, die ich entbehren kann, versucht verzweifelt, die anderen zu reparieren und startklar zu machen. Unsere Infanterie kann nicht mehr lange ausharren. Nehmt diese Ausrüstung und helft bei der Löschung der brennenden Bomber.", sourceObjective = "Löscht 6 Feuer auf dem Flugplatz von Eisenschmiede mit Eurer Feuerwehrausrüstung.", completion = "Gut gemacht! Meine Männer arbeiten hart daran, unsere Flugmaschinen und die Dampfpanzer kampfbereit zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26079] = { id = 26079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Falkenstein und Otto", description = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein ist für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.\n\nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.\n\nIhre Kopfgelder können bei Hauptmann Nials abgeholt werden.", sourceObjective = "Bringt Ottos und Falkensteins Köpfe zu Hauptmann Nials bei der Zuflucht.", progress = "Hallo. Kommt Ihr, um Bericht zu erstatten?", completion = "Falkenstein und Otto? Wunderbar!\n\nHier ist Eure Belohnung, {name}. Ich freue mich, sie auszuzahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26080] = { id = 26080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Gefallen", description = "{name}, Ihr müsst das hier zu Käpt'n Glovaal bringen. In meinem Zustand bräuchte ich sicher eine Woche, um zur Dämmerbucht zu gelangen. Aber wir haben keine Zeit zu verlieren!", sourceObjective = "Bringt Grabungslieds Fisch und Tipps zu Kapitän Glovaal in der Dämmerbucht.", progress = "Chabt Ihr Oskar und Humphrey gefunden?", completion = "Ich verstehe. Ja, ich mich erinnere jetzt… Humphrey und Oskar waren nicht die besten Schwimmer.\n\nDie Informatjionen sind sehr chilfreich und der Fisch sieht sich sehr ljecker aus. Wenn Ihr Cherr Grabungslied seht, bevor er zurückkehrt, bitte sagt ihm danke von mjir.", sourceObjectiveStatus = "unverified-source-field" }
quests[26081] = { id = 26081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alinas Belohnung", description = "Hier endet also die Geschichte von Trol'kalar. Diese Waffe wird im Namen der Dunklen Fürstin den Lebenden den Tod bringen.\n\nVerlasst mich jetzt, {name}. Es obliegt mir erneut, die Klinge zu bewachen. Berichtet Alina von Eurem Sieg. Sie wird Euch sicherlich belohnen", sourceObjective = "Sprecht mit Dunkelruferin Alina.", completion = "Die Nachricht von Eurem Sieg stimmt mich zufrieden, {class}... ein seltenes Gefühl. Die Dunkle Fürstin glaubt, unsere Eroberung von Lordaeron wäre vielleicht die einzige Möglichkeit, den Verlassenen wahre Zufriedenheit zu schenken, vielleicht sogar Erleichterung.\n\nDoch das spielt keine Rolle. Unser Sieg ist unausweichlich. Für Eure Loyalität im Dienste der Verlassenen belohne ich Euch im Namen von Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26082] = { id = 26082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Kriegsnarbe!", description = "Ich werde dem alten Narr erlauben, seinen Fall vorzutragen. Er behauptet, er könne Beweise dafür bringen, dass die Nachtelfen keine Massenvernichtungswaffe besitzen. Wir werden sehen.\n\nWährend wir auf diesen Beweis warten, werdet Ihr unsere Armee im Tal unterstützen. Zu diesem Zweck haben wir eine große Anzahl Belagerungspanzer vorbereitet. Unsere Verwüster sind angriffsbereit.\n\nNehmt den Fahrstuhl hinunter zum Boden des Außenpostens und übernehmt einen Verwüster von Krom'gar. Vernichtet damit unsere Feinde im Kriegsnarbental.", sourceObjective = "Benutzt den Verwüster von Krom'gar, um 5 darnassische Glevenschleudern und 20 beliebige Soldaten der Allianz im Kriegsnarbental zu vernichten.", progress = "Tötet sie alle!", completion = "Ihr beweist ein ziemliches Zerstörungstalent, {name}. Die Allianzsoldaten, die nach Eurer wilden Fahrt durch das Kriegsnarbental noch übrig sind, wird die Bombe erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26083] = { id = 26083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallo Lolo", description = "Gichtdarm war geschickt spähen. Guckt viele Dinge. Groß Abenteuer!\n\nGichtdarm findet geheim Piratschiff. Piraten viel Angst, laufen weg. Aber Oger Lolo nicht laufen. Lolo macht gut Freund mit Gichtdarm!\n\nGichtdarm muss weg, aber vermissen Lolo. Ihr sagen hallo zu Lolo von Gichtdarm.", sourceObjective = "Findet Lolo den Ausguck in der Faldirbucht.", completion = "Ihr Freund von Gichtdarm! Er komisch Oger. Riechen seltsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[26084] = { id = 26084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerfall", description = "Ihr habt uns hier gut gedient, {name}. Wir haben ein Zeichen gesetzt, aber die nächste Phase unseres Eroberungsfeldzugs wird Monate brauchen, nicht nur Minuten.\n\nEs gibt noch viel zu tun. Ich werde Euch den langweiligen Teil - das Warten auf das Eintreffen der Wehrbefestigungen - ersparen. Reist gen Osten nach Hammerfall. Die Orcs dort werden Eure Hilfe gebrauchen können.", sourceObjective = "Meldet Euch bei Gor'mul in Hammerfall im Arathibecken.", completion = "Throm'ka, {class}. Wenn Eure Taten für die Untoten so bemerkenswert waren, wie Ihr sagt, fühle ich mich geehrt, Euch beim Dienst für die Horde zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26085] = { id = 26085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt die Verteidiger", description = "Während unsere Ingenieure dafür sorgen, dass die Bomber bald wieder fliegen, kämpfen unsere Wachen und Gebirgsjäger gegen die Eindringlinge.\n\nSeit Beginn des Einmarschs sind sie dort draußen, ohne Zeit für Schlaf oder Essen. Die Verteidiger von Eisenschmiede gehören zu den besten Azeroths, aber selbst sie haben Grenzen.\n\nNehmt diese Banner und platziert sie in Verwehungen aus losem Schnee. Erinnert die Soldaten an das, wofür sie kämpfen und stärkt ihre Moral.", sourceObjective = "Platziert 8 Banner von Eisenschmiede in Hügel aus losem Schnee überall auf dem Flugplatz von Eisenschmiede.", completion = "Die Soldaten entdecken verborgene Reserven der Stärke und des Mutes und werfen sich den Dunkeleisenzwergen entgegen. Solange wir hier sind, wird der Flugplatz nicht fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26086] = { id = 26086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orako", description = "<Kapitän Verne sieht auf seine Uhr.>\n\nWo ist dieser Jäger? Ich habe Orako vor einer Woche in die Tiefenlichtkluft geschickt, um einen Bericht zu schreiben! Ja, er ist schon ganz schön anstrengend und ich hätte nichts dagegen, ihn vom Hals zu haben, aber ich brauche seinen Bericht.\n\nIhr da! Wie heißt Ihr? {name}? Würdet Ihr ihn für mich ausfindig machen? Es scheint zwar merkwürdig, dass <ein/eine:c> {class} einen Jäger suchen soll, aber mir bleibt keine andere Wahl.", sourceObjective = "Meldet Euch bei Orako bei der Tiefenlichtkluft in Vashj'ir.", completion = "Gah! Diese Fische sind einfach nicht zu treffen!\n\n<Orako schaut Euch an.>\n\nMein Wolf wurde von einem Fisch gefressen und ich gehe nicht zurück, bis ich ihn gefunden habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26087] = { id = 26087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtsaft", description = "Es ist einfach, einen Fisch in einem Fass zu erschießen. Einen Fisch in einem Meer zu erschießen ist da schon schwieriger.\n\nHabt Ihr die Murlocs unten in der Kluft gesehen, {class}? Sie schießen überhaupt nicht! Sie tragen kleine Kugeln voller Leuchtsaft auf dem Kopf, dank derer die Fische zu IHNEN kommen. He, das sollten wir auch versuchen!\n\nGeht nach Süden und tötet die Krebse und Barsche in der Kluft. Sie haben haufenweise Leuchtsaft in ihrer Haut. Ich habe es genau gesehen!", sourceObjective = "Besorgt Euch 6 Einheiten Leuchtsaft von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", progress = "Wir brauchen haufenweise Leuchtsaft!", completion = "Schaut nur, wie das leuchtet!\n\n<Orako blickt sehnsüchtig in die Ferne.>\n\nMein Wolf hat leuchtende Dinge geliebt…", sourceObjectiveStatus = "unverified-source-field" }
quests[26088] = { id = 26088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hierher, Fischlein Fischlein!", description = "<Orako formt einen Ball aus dem Leuchtsaft und bringt ihn dann an einem Gerät an, an dem er offensichtlich schon lange bastelt.>\n\nHier, ich habe einen Hut für Euch. Er hat ein Licht, das Fische anlockt. Genau wie bei den Murlocs!\n\nDie Murlocs jagen gerne im Tang und in den Korallen an den Seiten der Kluft. Wenn Ihr diesen Hut aufsetzt und durch den Tang schwimmt, könnt Ihr vielleicht genauso Fische fangen, wie sie.", sourceObjective = "Setzt den Fischerhut auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", progress = "Wie viele habt Ihr gefangen?", completion = "Hm… Ihr habt ganz schön viele Fische, aber das sind nicht die, die meinen Wolf gefressen haben. Ich schätze, es war ein größerer Fisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26089] = { id = 26089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirb, Fischmann, stirb", description = "Ein Fisch hat meinen Wolf gefressen, und Murlocs sehen aus wie Fische. Diese Murlocs werden bezahlen!\n\nGeht zurück in die Kluft und tötet diese Fischmänner! Mein Wolf wird seine Rache bekommen!", sourceObjective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", completion = "Ich weiß, dass Murlocs keine Fische sind. Ich dachte nur, sie zu töten würde meine Laune heben. Aber ich bin immer noch traurig wegen meines Wolfs.\n\n<Orako seufzt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26090] = { id = 26090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier, ein Ei!", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Orako vielleicht daran interessiert sein könnte.>", sourceObjective = "Bringt das enorme Aalei zu Orako bei der Tiefenlichtkluft in Vashj'ir.", progress = "<Bamm!>\n\nIhr habt mir etwas mitgebracht?", completion = "Das ist ein großes Ei.\n\n<Orako schnüffelt daran.>\n\nEs ist groß und es riecht nach Fisch. Vielleicht ist der große Fisch, von dem dieses Ei stammt, ja der, der meinen Wolf gefressen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[26091] = { id = 26091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hierher, Fischlein Fischlein, Teil 2: Der Eier-Aal-Trick-Blues", description = "<Orako nimmt eine Sprengfalle aus seiner Tasche und schiebt sie durch die äußere Hülle des Eis.>\n\nJetzt wird das Ei explodieren. Legt es in der Nähe eines dieser gigantischen Aale ab und wartet, bis er näher kommt. Wenn das Ei explodiert, ist der große Fisch schon halbtot und Ihr könnt ihn leicht erledigen.\n\nRettet meinen Wolf! Mit diesem Ei wird es Euch gelingen.", sourceObjective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", completion = "<Orako spielt ausgiebig mit Wolf.>\n\nOh, vielen Dank, {name}! Ich wusste, dass Wolf noch lebt!\n\nHier, bedient Euch. Ich habe dafür keine Verwendung mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[26092] = { id = 26092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orakos Bericht", description = "<Ihr erinnert Orako daran, dass er einen Bericht an Kapitän Verne senden sollte.>\n\nStimmt, ein Bericht. Alles, was ich hier gesehen habe, sind Fische. Fische, Fische und nochmals Fische.\n\n<Orako wirft einen Blick auf den Sack Fische, den Ihr ihm mitgebracht habt.>\n\nBringt das zurück zum Kapitän. Das ist mein Bericht.", sourceObjective = "Bringt Orakos Bericht zu Kapitän \"Juwel\" Verne in der Schattenhöhle.", progress = "Wo war er? Was ist passiert?", completion = "Das ist sein Bericht?! Dieser Idiot…\n\nIch schätze, wir können die Nahrung gut gebrauchen. Danke, {name}. Ihr habt Eure Aufgabe so gut erledigt, wie ich es erwartet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26093] = { id = 26093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordhof", description = "Wir kämpfen in einem Krieg um Stromgarde und wir verlieren. Die Oger, das Syndikat und wir selbst haben unsere einst mächtige Stadt zerrissen und jede Fraktion kämpft mit der anderen bis zu einem blutigen Patt.\n\nAber unsere Truppen werden dezimiert, während die Zahl der Feinde ansteigt.\n\nAuch wenn Süderstade gefallen ist, dürfen wir unseren Feinden keinen Fußbreit unseres Bodens mehr überlassen! Wir müssen das Land für uns zurückerobern, bevor die Horde die Gelegenheit hat, sich weiter auszubreiten.", sourceObjective = "Tötet 10 Mitglieder des Syndikats.", completion = "Sehr gut, {name}. Das letzte, was wir bei der Bedrohung durch die Untoten noch brauchen, ist ein Angriff von einer Bande gewöhnlicher Diebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26094] = { id = 26094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenschlag", description = "Mein Chefingenieur sagt, dass er einen der Bomber repariert hat. Er ist startbereit. Nehmt diese Bomben und sucht den reparierten Bomber am Anfang der Rollbahn.\n\nSetzt die Bomben ein, sobald Ihr in der Luft seid, und richtet unter den angreifenden Dunkeleisenzwergen so viel Schaden wie möglich an. Ich habe Gerüchte gehört, laut derer sie eine neue Art von Kriegsgolem einsetzen wollen. Sucht nach diesen Golems. Sie sind Eure wichtigsten Ziele.", sourceObjective = "Steigt in den reparierten Bomber und tötet 30 Angreifer der Dunkeleisenzwerge mit der Eisenhammerbombe. Ihr könnt beliebige Dunkeleisenzwerge oder ihre Verbündeten auf dem Flugplatz töten.", completion = "Das Blatt wendet sich, {name}, größtenteils dank Eurer Leistungen. Jetzt müssen wir den Anführern der Dunkeleisenzwerge einen Schlag versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26095] = { id = 26095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen von Stromgarde", description = "Das Syndikat in Stromgarde kämpft dort gegen unsere Milizeinheiten. Um den Abschaum dazu anzustacheln, unsere disziplinierteren Truppen anzugreifen, hat das Syndikat ein Kopfgeld auf unsere Soldaten ausgesetzt. Sie belohnen jedes Abzeichen von Stromgarde, das einem toten Milizsoldaten abgenommen wird, mit Gold.\n\nWir wollen diese Abzeichen wieder haben. Diese Halsabschneider dürfen keine Trophäen unserer mutigen Gefallenen behalten!\n\nBetretet den vom Syndikat kontrollierten Teil von Burg Stromgarde und bringt unsere Abzeichen an Euch.", sourceObjective = "Erbeutet 7 Abzeichen von Stromgarde vom feindlichen Syndikat in Burg Stromgarde.", progress = "Konntet Ihr Abzeichen von Stromgarde erbeuten, {name}? Das Syndikat muss begreifen, dass es von unseren Toten nicht profitieren wird.", completion = "Danke, {name}. Wir werden den Familien dieser gefallenen Soldaten mitteilen, dass sie im Kampf getötet wurden.\n\nSelbst schlimme Nachrichten sind besser als im Ungewissen über das Schicksal eines Angehörigen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26096] = { id = 26096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrühende Pilze", description = "Wir glauben, dass wir eine gute Verwendung für die Gnadenlosen gefunden haben, die Euer Freund aus der Höhle uns gebracht hat. Ich benötige jedoch ein Konservierungsmittel dafür.\n\nUnten im Brühgraben findet Ihr Pilze, die genau die Eigenschaften haben, die ich brauche. Bringt mir ein paar davon und ich schaue, was ich tun kann.", sourceObjective = "Sammelt 5 Verbrühende Pilze.", progress = "Ich habe gehört, dass Ihr ein unangenehmes Erlebnis hattet, als Ihr Euch einen der Dämonen auf den Kopf gesetzt habt. Ich kann Euch jedoch versichern, dass sie jetzt alle mausetot sind.", completion = "Ich werde die Pilze als Reagenz benutzen, um die Kadaver einzubalsamieren. Wir haben gleich einen für Euch vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26097] = { id = 26097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis für eine Lüge", description = "Im Herzen des Kriegsnarbentals steht ein uralter Baum - ein Baum, der den Zeitaltern widerstanden hat und seit Generationen als ein Ort des Friedens und der Lehre genutzt wird. Solange ich denken kann, hat meine Familie in diesem Hain zusammen mit den Nachtelfen das Druidentum studiert. Und jetzt soll ich glauben, dass sich in diesem Baum eine Massenvernichtungswaffe der Allianz befindet?\n\nKrom'gar irrt sich. Das werde ich beweisen!\n\nIch habe meinen Sohn Orthus in den Hain von Thal'darah geschickt. Er soll nach der Waffe suchen. Geht dorthin und trefft ihn.", sourceObjective = "Findet Orthus im Hain von Thal'darah im Steinkrallengebirge.", completion = "Orthus ist tot. Er hält etwas in der Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26098] = { id = 26098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat im Hain", description = "Der Raum ist voller toter Druiden. Etwas stimmt nicht, denn Ihr seht keine Anzeichen eines Kampfes. Von der Tür führen blutige Schleifspuren ins Innere.\n\nIhr öffnet Orthus' erstarrte Faust und findet etwas verstörendes: ein Insigne des Generals von Krom'gar.\n\nBringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer.", sourceObjective = "Bringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer am Klippenläuferposten im Steinkrallengebirge.", progress = "Er... Mein Kind ist tot?", completion = "<Ihr gebt Oberhäuptling Klippenläufer das Insigne.>\n\n<Oberhäuptling Klippenläufer schreit wütend auf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26099] = { id = 26099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das soll Gerechtigkeit sein?", description = "Er war ein guter Junge, {name}. Jung, liebevoll. Niemals hätte er einen der jungen Druiden getötet. Sie waren seine Freunde! Nein... Nicht Orthus.\n\nDer General muss sich für dieses Verbrechen verantworten. Ich verlange Gerechtigkeit!", sourceObjective = "Verteidigt Euch.", progress = "Das ist gerecht.", completion = "Ihr habt es mit eigenen Augen gesehen, {name}. General Grebo hat uns angegriffen!\n\n\n\nWas sollen wir jetzt tun? Der Kriegshäuptling wird uns als Verräter hinrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26100] = { id = 26100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der General ist tot", description = "Würdet Ihr mit Oberanführer Krom'gar reden, {name}? Vielleicht hört er ja auf Euch. Ihr seid schließlich ein Champion in seiner Armee. Ihr habt alles gesehen. Bitte helft uns, {name}. Wir wollen doch nur in Frieden gelassen werden.\n\nSprecht mit Oberanführer Krom'gar und versucht ihm zu vermitteln, dass wir nicht wollten, was geschehen ist.", sourceObjective = "Sprecht mit Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", completion = "WAS? Die Tauren haben meinen General umgebracht? Das ist Verrat! HOCHVERRAT! Für diesen schweren Fehler werden sie bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26101] = { id = 26101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über dem Gesetz", description = "Es war richtig, dass Ihr mir dieses Verbrechen gemeldet habt. Die Täter werden für dieses feige Verbrechen bezahlen. Blut wird fließen.\n\nOhne Grebo fehlt mir ein General. Ihr werdet seinen Platz einnehmen.\n\nTrefft mich am Klippenläuferposten, General. Zusammen werden wir diesen Schwachsinn beenden.", sourceObjective = "Trefft Oberanführer Krom'gar am Klippenläuferposten im Steinkrallengebirge.", completion = "Der verräterische Tauren wird zusehen, wie wir seinen geliebten Hain vernichten und sein Dorf niederbrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26102] = { id = 26102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmaxts Ende", description = "Dank eures Einsatzes ist der Angriff der Dunkeleisenzwerge ins Stocken geraten. General Grimmaxt, der Anführer der Dunkeleisenzwerge, versucht, seine Truppen aus ihren Reihen auf dem gefrorenen See im Süden anzutreiben.\n\nEr steht auf einem ihrer neuen Dunkeleisengolems und ruft seinen Soldaten Befehle zu. Wenn es ihm gelingt, sie zu motivieren, überrennen sie uns vielleicht doch noch. Das müsst Ihr verhindern, {name}. Zerstört den Golem, der General Grimmaxt beschützt, dann ihn selbst. Er ist der Schlüssel zu unserem Sieg.", sourceObjective = "Tötet General Grimmaxt auf dem Flugplatz von Eisenschmiede.", completion = "Geschafft! Ohne Eure Hilfe hätte der Feind den Flugplatz von Eisenschmiede erobert. Dann hätten die Dunkeleisenzwerge freie Bahn bis Eisenschmiede gehabt.\n\nDer Rat der Drei Hämmer muss erfahren, was hier geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26103] = { id = 26103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biotreibstoff", description = "Unterseeboottreibstoff ist teuer!\n\nDie Machthaber in Gnomeregan waren so freundlich, uns mehrere Treibstofffässer zur Verfügung zu stellen, aber wir verbrauchen sie schneller als erwartet. Das bedeutet, dass wir improvisieren müssen.\n\nEs ist kein Geheimnis, dass die Meereslebewesen allerlei interessante Chemikalien enthalten... wie zum Beispiel Öl. Bringt dieses Gerät zu Korthuns Ende und benutzt es an Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Wenn wir nicht mehr Unterseeboottreibstoff beschaffen können, ist ihr Öl vielleicht unsere einzige Hoffnung.", sourceObjective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", progress = "Wie hat das Gerät funktioniert, {name}?", completion = "<Ingenieur Hexasept steckt einen Finger in jede Probe und schnuppert daran.>\n\nJa, das sollte klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26105] = { id = 26105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erobert Korthuns Ende", description = "Die Horde hat Spione in dieser Gegend? Die Dämmerbucht ist ganz in der Nähe und die Zange X2 befindet sich dort! Die Horde darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Dämmerbucht darüber informieren… nachdem Ihr mehr von diesen dreckigen Spionen der Horde den Garaus gemacht habt!", sourceObjective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", completion = "Das habt Ihr gut gemacht, {name}. Zur Zeit müssen wir besonders vor Angriffen der Horde auf der Hut sein. Die Zange X2 hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26106] = { id = 26106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoffologie leicht gemacht", description = "Wie viel wisst Ihr über Treibstoff, {name}? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Treibstofftestanlage in der Dämmerbucht, um den perfekten Biotreibstoff herzustellen.", progress = "Wir haben noch nicht die richtige Kombination gefunden, {name}. Macht weiter! Ich bin mir sicher, dass Ihr es schafft.", completion = "Habt Ihr je daran gedacht, eine wissenschaftliche Karriere anzustreben, {name}? Wenn Ihr je genug von Eurem derzeitigen Metier habt, meldet Euch bei mir. Ich könnte einen Assistent mit Eurer Passion für Experimente und wissenschaftliche Arbeit brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26107] = { id = 26107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmungsaufheller", description = "Dank der Schamanenkünste unseres Volkes konnte ich Jahre der Lethargie hinter mir lassen. Jetzt sorge ich für alle hier und stelle den Segen her, der auch mir neue Kraft schenkte.\n\nDie Hochlandraptoren sind tückische und wilde Bestien. Ihre Geister können unseren Kriegern große Stärke geben. Bringt mir Raptoraugen, damit ich die Amulette herstellen kann, so wie es mich Tor'gan lehrte.", sourceObjective = "Erbeutet 10 Hochlandraptoraugen von Hochlandschreitern oder Hochlandhauern.", progress = "Die Wildheit in den Augen der Raptoren wird auf unsere Krieger übergehen.", completion = "Die Lethargie, die mich nach dem Fall unserer Lager überkam, war so stark, dass ich das Geschenk ablehnte, als man es mir anfangs machte.\n\nNun bin ich stolz darauf, meinen Anteil im Namen der Horde zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26108] = { id = 26108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arglist des Raptors", description = "Die Hochlandfleischpirscher sind noch wilder als ihre Artgenossen. Sie besitzen nicht nur Stärke, sondern auch große List.\n\nAls ich in der Lethargie gefangen war, konnten mich selbst Amulette der Stärke nicht bewegen. Doch Tor'gan benutzte die Herzen der Fleischpirscher, um mich mit einem Geist zu erfüllen, der meine Zweifel besiegte und mich befreite.\n\nUnsere Soldaten verdienen die List des Raptors. Sammelt Fleischpirscherherzen für mich, {name}.", sourceObjective = "Sammelt 12 Raptorherzen von Hochlandfleischpirschern.", progress = "All meine Vorbereitungen sind getroffen, jetzt brauche ich nur noch die Raptorherzen.", completion = "Ich übertrage die Macht und den Geist der Raptoren in diese Kugel, so wie es mich Tor'gan gelehrt hat. Sie wird die Krieger mit der wilden Stärke und der Intelligenz des Raptors erfüllen.\n\nDie List des Raptors erfüllt Euch nun auch, {class}. Nehmt sie mit Stolz an. Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26110] = { id = 26110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie in alten Zeiten", description = "Schon seltsam. Kin und ich haben so einiges zusammen durchgemacht und doch finden wir uns in Arathi wieder, wie schon vor so vielen Jahren.\n\nHier vereitelten wir einen Plan zur Schaffung einer neuen Seuche, sie und ich. Die Horde scheint ihre Lektion nicht gelernt zu haben, denn es wimmelt schon wieder von ihnen auf diesem Hof.\n\nIhr untoter Kurier schlurft für jeden sichtbar umher. Ihr könnt uns helfen. Findet den Kurier und bringt mit, was auch immer er bei sich trägt.", sourceObjective = "Nehmt dem Kurier der Verlassenen den versiegelten Ordner ab.", progress = "Vielen Dank für Eure Hilfe bei der Suche nach dem Kurier, {name}.\n\nWährend Eurer Abwesenheit sah Kin einen Apotheker, der aus dem gleichen Haus südlich von hier kam. Ich bin mir sicher, dass sie nichts Gutes im Schilde führen -- ich brauche nur einen Beweis, damit wir nicht unüberlegt handeln.\n\nHattet Ihr Glück?", completion = "Schon wieder Apotheker. Die kapieren es einfach nicht. Mal sehen, was dieses Mal los ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[26111] = { id = 26111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "… und er wird kommen", description = "Ich erfülle Euch nun mit den Energien des verderbenden Gesichtslosen.\n\nSchwimmt hinunter zu meinem Ködertotem im Graben im Nordosten. Nutzt das Totem, um die Energien zu entfesseln. Bringt mir das Gehirn ihres Anführers.\n\nRuft Ick'thys den Unergründlichen… und er wird kommen!", sourceObjective = "Besorgt Euch das Gehirn des Unergründlichen.", progress = "Habt Ihr es, {name}?\n\nMit dem Gehirn des Unergründlichen können wir vielleicht doch mit L'ghorek, dem sterbenden Ahnen vor uns, kommunizieren.", completion = "Und nun schauen wir mal, ob wir Euch in L'ghorek versetzen können, damit Ihr mit ihm sprecht, bevor er stirbt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26112] = { id = 26112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfällige Antworten", description = "Wie genau ist es den Kriegern der Dunkeleisenzwerge gelungen, bis hierher vor die Tore Eisenschmiedes zu kommen und beinahe unsere Stadt zu erobern?\n\nHerrscht nicht 'Kaiserin' Moira, Mitglied unseres hochgeschätzten Rates der Drei Hämmer, über die Dunkeleisenzwerge? Ohne ihr Wissen und ihre Zustimmung konnte das nicht geschehen. Das war keine zusammengewürfelte Gruppe rebellischer Zwerge, sondern eine gut ausgerüstete Invasionsstreitmacht.\n\nIch habe einen Bericht über die Schlacht um den Flugplatz zusammengestellt. Bringt ihn zum Hohen Sitz nach Eisenschmiede und konfrontiert sie damit!", sourceObjective = "Bringt Steinbrechers Bericht zu Moira Thaurissan im Hohen Sitz von Eisenschmiede.", progress = "Was hat diese Störung zu bedeuten?", completion = "Und was genau ist das?\n\n<Moira nimmt den Bericht entgegen. Sie wird blass, als sie ihn liest.>\n\nDas ist unmöglich!", sourceObjectiveStatus = "unverified-source-field" }
quests[26113] = { id = 26113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae und Kinelory", description = "Die Horde besetzt Go'sheks Hof im Osten schon seit langem. Bei all unseren anderen Problemen hier fiel das nicht ins Gewicht. Aber nun gibt es Berichte über Untote in diesem Gebiet.\n\nAlles, was alarmierender ist als ein paar schlurfende Peons, gibt Anlass zu Nachforschungen. Das ist nicht das erste Mal, dass die Untoten auf dem Hof ihre dunklen Pläne vorantreiben. Ich habe meine besten Späher dorthin geschickt. Meldet Euch bei Quae und Kinelory. Sie werden Euch alles erzählen.", sourceObjective = "Findet Quae auf dem Hügel über Go'sheks Hof.", completion = "Die Zuflucht schickt Euch? Schön, dass es sie noch gibt.\n\nWir haben hier ein paar interessante Dinge beobachtet, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26114] = { id = 26114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae vertraut Euch", description = "<Quae sieht die Unterlagen durch.>\n\nAusdehnung...Gebietskontrolle... diese Untoten planen nichts neues, aber sie wollen ganz Arathi einnehmen. Wir müssen ihre Pläne stören.\n\nIch halte hier oben Wache. Ihr geht mit Kin und besorgt die Invasionspläne. Diese wandelnden Kadaver werden nicht einmal erfahren, welchen Tag wir haben.\n\nUnd passt auf sie auf, verstanden?", sourceObjective = "Sprecht mit Kinelory nahe Go'Sheks Hof im Arathihochland.", completion = "Die Seuche nahm uns unsere Freunde und Familien, aber die Verlassenen nahmen uns Phin. Sie sind nicht besser als die Geißel. Ich werde sie alle mit meinen eigenen Händen töten, wenn es sein muss.\n\nSagt Bescheid, wenn Ihr bereit seid. Wir können direkt anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26115] = { id = 26115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sehen ist verstehen", description = "Bleibt bei mir, {name} und seht zu, wie unsere mächtige Waffe den Feind vernichtet!\n\nVersteht, was es bedeutet, zur Horde zu gehören!", sourceObjective = "Versteht, was es bedeutet, zur Horde zu gehören.", progress = "Habt Ihr es verstanden?", completion = "Jetzt endlich wisst Ihr, was es heißt, ein Mitglied der Horde zu sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26116] = { id = 26116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinelory schlägt zu", description = "Also gut, {name}. Wenn Ihr soweit seid... \n\nWollen wir?", sourceObjective = "Beschützt Kinelory, bis sie zu Quae zurückkehrt.", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}. Danke.\n\nHoffentlich hat Euch Kin keine Probleme bereitet. Sie ist sehr zuvorkommend, aber tödlich für ihre Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26117] = { id = 26117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Süderstade", description = "Es gab Abende in der Taverne, nach denen Kinelory schlimmer aussah als jetzt. Ihr habt sie anscheinend gut beschützt.\n\nDie Zuflucht sollte von unserem Erfolg erfahren. Ich bleibe mit Kin hier, damit sie sich ausruhen kann. Geht ohne uns los.", sourceObjective = "Kehrt zu Kommandantin Amaren in der Zuflucht zurück.", completion = "Ich bin wirklich beeindruckt, {class}. Bei all dem, was hier geschieht, ist dies ein kleiner Trost.\n\nIhr habt die Untoten bekämpft, die Horde zurückgeworfen und die Opfer von Süderstade geehrt. Im Namen des Königreichs von Stromgarde verleihe ich Euch eine offizielle Belobigung und diese Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26118] = { id = 26118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasst den Botschafter", description = "Der Verrat des Botschafters wird mich noch lange verfolgen. Ihr müsst ihn verhaften, bevor er noch weiteren Schaden anrichtet oder schlimmer noch, bevor er entkommt und mit der Planung des nächsten Angriffs beginnt. Eisenschmiede wird erst sicher sein, wenn Botschafter Schlackenhammer sich nicht mehr frei in der Stadt bewegt.\n\nNehmt diese Fesseln und geht zur Botschaft der Dunkeleisenzwerge. Sie befindet sich nördlich des Hohen Sitzes, am Rand der Großen Schmiede. Verhaftet Botschafter Schlackenhammer und kehrt mit ihm zurück.", sourceObjective = "Geht zur Botschaft der Dunkeleisenzwerge und verhaftet Botschafter Schlackenhammer mit Hilfe der stabilen Handfesseln.", completion = "Der Botschafter wird uns keinen Ärger mehr machen. Er ist nicht der einzige Dunkeleisenzwerg, dessen Herz immer noch für den Schattenhammer schlägt. Das dürfen wir nie vergessen. Wir müssen wachsam sein und ihre Pläne vereiteln, sonst wird mein Sohn nur Ruinen und Asche erben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26120] = { id = 26120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wahnsinnige Orc des Drachenmals", description = "Die Orcs des Drachenmals werden immer mehr zur Plage. Ihre waghalsigen Angriffe auf den Hain sind zwar lästig, verhelfen meinen Wachen aber wenigstens zu einigen nützlichen Übungseinheiten.\n\nMeine Späher haben jedoch beobachtet, dass sie schwarze Großdrachenwelpen mit Netzen einfangen. Das letzte, was dieses Land gebrauchen kann, ist ein primitives Wiederaufleben der Drachenzähmung. Macht Euch auf den Weg nach Osten, {class}, und tötet die Welpendiebe. Sorgt dafür, dass ihre Dummheit uns nicht teuer zu stehen kommt.", sourceObjective = "Tötet 12 Welpendiebe des Drachenmals.", completion = "Die Orcs haben verstanden, dass sie nicht weiter nach Westen vordringen dürfen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26121] = { id = 26121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erobert Korthuns Ende", description = "Ihr seht Spione da oben? Das ist nix gut… gar nix gut, <Genosse/Genossin>.\n\nKehrt zurück zu Korthuns Ende und vernichtet sie, mein Freund.", sourceObjective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[26122] = { id = 26122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umweltbewusstsein", description = "Habt Ihr je Unterseeboottreibstoff gerochen, {name}? Widerliches Zeug. Leider müssen wir große Mengen davon verbrennen, um die Verne anzutreiben. Und es riecht nicht nur abstoßend, sondern ist auch tödlich für die Tiere hier. Wir müssen bewusster mit unserer Umwelt umgehen.\n\nDie Meereswesen hier in der Gegend haben besonders öliges Fleisch. Bringt dieses Gerät zum Meeresdickicht direkt über dieser Höhle und benutzt es an den Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Ihr Öl kann vielleicht das Leben Hunderter anderer Meereslebewesen retten.", sourceObjective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", progress = "Bitte… Sagt den anderen Goblins nicht, dass ich Umweltschützer bin! Ich könnte ihren Spott nicht ertragen!", completion = "<Fiasco steckt einen Finger in jede Probe und schnuppert daran.>\n\nJa, das sollte klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26124] = { id = 26124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert das Meeresdickicht", description = "Die Allianz hat Spione in dieser Gegend? Die Schattenhöhle ist ganz in der Nähe und das neue Unterseeboot der Horde, die Verne, befindet sich dort! Die Allianz darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Höhle darüber informieren… nachdem Ihr mehr von diesen hinterhältigen Spionen der Allianz den Garaus gemacht habt!", sourceObjective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", completion = "Das habt Ihr gut gemacht, {name}. Zur Zeit müssen wir besonders vor Angriffen der Allianz auf der Hut sein. Die Verne hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26125] = { id = 26125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert das Meeresdickicht", description = "Ihr habt da oben Spione gesehen? Das ist nicht gut… Das lasse ich nicht zu!\n\nKehrt zum Meeresdickicht zurück und werdet sie los, bevor sie sich in unser Versteck einschleichen können.", sourceObjective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26126] = { id = 26126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Treibstoff", description = "Wie viel wisst Ihr über Treibstoff, {name}? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Treibstofftestanlage in der Schattenhöhle, um den perfekten Biotreibstoff herzustellen.", completion = "Das war's. Ab heute werde ich die Verne mit Biotreibstoff betreiben. Ich werde ein paar Männer nach oben schicken, um mehr Öl zu besorgen.\n\nDenkt nur an die ganzen Meerestiere, die wir heute gerettet haben, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26127] = { id = 26127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Enthüllung des Schattenhammers", description = "Ich dachte ebenso wie alle anderen, dass es sich bei diesen Narren nur um nichtsnutzige Dunkeleisenzwerge handelte, aber diese Wahnsinnigen sind überzeugte Kultisten!\n\nDer Schattenhammer will nichts anderes als die Zerstörung der ganzen Welt. Sie haben sich Todesschwinge und Ragnaros angeschlossen und sind eng mit den Dunkeleisenzwergen verbunden.\n\nAber es ist egal, wer sie sind, wichtig ist nur, dass sie sich in Dun Modr aufhalten und entfernt werden müssen! Ich werde keinen von ihnen durchlassen. Geht zu ihnen und zertrümmert ein paar Schädel!", sourceObjective = "Tötet 12 Mitglieder des Schattenhammers in Dun Modr.", completion = "Gute Leistung, Junge, aber wir haben keine Zeit für Feste. Der Thandolübergang wird bedroht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26128] = { id = 26128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Thandolübergang", description = "Ich habe den Thandolübergang schon einmal vor der Zerstörung bewahrt. Damals kämpfte ich gegen die Dunkeleisenzwerge. Das gleiche tat mein Vater und dessen Vater vor ihm...\n\nDie einzigen Dunkeleisenzwerge, die mir entkamen, liefen direkt auf die Brücke zu. Etwas stimmt nicht. Ich befürchte, dass wir bei unserer Ankunft in eine üble Falle stürmen werden.\n\nIch könnte Eure Hilfe brauchen, {name}. Für Eisenschmiede. Seid Ihr dabei?", sourceObjective = "Besiegt Calamoth Aschbart am Thandolübergang.", completion = "Gut, dass wir den los sind!\n\nDank Euch ist der Thandolübergang sicher, {name}. Ich hoffe, dass Calamoth nicht noch einmal zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26129] = { id = 26129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffenbrüder", description = "Hört zu, {name}. Zum ersten Mal seit dem Bürgerkrieg bin ich mit Graumähne einer Meinung. Es ist an der Zeit, unsere Fehde endlich beizulegen.\n\nDiesen Bestien scheint es egal zu sein, ob man Rebell oder Königstreuer ist.\n\nÜberbringt Graumähne meine Antwort. Meine Männer werden sich seinen Leuten anschließen.\n\nNicht weit von hier gibt es ein sicheres Versteck, in Josiahs Keller. Meine Jungs haben dort ein wenig schwere Artillerie gelagert.\n\nSagt dem König, dass er sich jederzeit in unserer Waffenkammer bedienen kann.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel in Gilneas.", completion = "Eine Waffenkammer der Rebellen? In meiner eigenen Stadt?\n\nWas zur Hölle führte Crowley nur im Schilde?", sourceObjectiveStatus = "unverified-source-field" }
quests[26130] = { id = 26130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Verbindung zu L'ghorek", description = "L'ghorek ist der Ahn, der auf der Klippe gegenüber von uns ruht. Er wird kontrolliert. Etwas Riesiges unter uns verschlingt seine Lebensenergien.\n\nUnter L'ghorek gibt es eine Höhle, die als Muscheltiefe bekannt ist. In dieser Höhle befinden sich drei mächtige Ogermagier, die ein Ritual abhalten, das das Ding aus der Tiefe mit dem Ahnen verbindet. Ihr müsst die drei töten, um die Verbindung zu L'ghorek zu unterbrechen.", sourceObjective = "Tötet Ur'Goz, Sku'Bu und Neph'Lahim.", completion = "Jetzt, da L'ghoreks Verbindung unterbrochen wurde, müssen wir versuchen, mit ihm Kontakt aufzunehmen. Ich kann spüren, dass der Ahn noch lebt, aber er ist sehr schwach.", sourceObjectiveStatus = "unverified-source-field" }
quests[26131] = { id = 26131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Loch Modan", description = "Seit Stunden warte ich darauf, dass sich der Rat meine Bitte anhört, aber es sieht nicht gut aus. Moira scheint darauf versessen zu sein, den Rat lahmzulegen.\n\nWährenddessen leidet Loch Modan. Wir haben viele Feinde, aber nur wenige Ressourcen. Würdet Ihr mich vielleicht anhören, {name}, wenn der Rat nicht dazu gewillt ist? Sprecht mit Gryth Thurden, dem Greifenmeister von Eisenschmiede. Er hält sich im östlichen Teil der Großen Schmiede auf. Er wird Euch kostenlos zum Südtorpass fliegen lassen. Stellt Euch nach Eurer Ankunft Pilot Hammerfuß vor.", sourceObjective = "Bittet Gryth Thurden in der Großen Schmiede um einen Flug nach Loch Modan. Sprecht bei Eurer Ankunft mit Pilot Hammerfuß.", completion = "Ihr könnt Euch nicht vorstellen, wie froh ich bin, neue Gesichter aus Eisenschmiede zu sehen. Vielleicht war es doch keine Verschwendung, Gebirgsjäger Gerstenbräu dorthin zu entsenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26132] = { id = 26132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheusale aus der Netherwelt", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nWir können nicht riskieren, dass sie diese Entartungen später gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, zerstört so viele von den Dingern, wie Ihr könnt.", sourceObjective = "Tötet 8 Netherscheusale.", completion = "Das Letzte, was wir brauchen, ist ein Haufen beschworener Kreaturen, die während unseres letzten Angriffs unsere Streitmächte anfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26133] = { id = 26133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheusale aus der Netherwelt", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nIch will nicht miterleben, dass sie diese Entartungen gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, vernichtet sie alle!", sourceObjective = "Tötet 8 Netherscheusale.", completion = "Eine Sache weniger, um die wir uns bei unserem letzten Angriff sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26134] = { id = 26134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts mehr für Euch hier", description = "Es gibt hier nichts mehr für Euch, {name}. Was mich betrifft, ich muss nur noch Mashas Leiche begraben. Wenn ich das getan habe, werde ich zur Bombenabwurfstelle gehen und das Nachwachsen einleiten. Vielleicht wird eines Tages ein neuer Hain erblühen - ein Hain erfüllt mit dem Geist meines Kindes und denen der gefallenen jungen Nachtelfen.\n\nIch habe von einem Blutelf namens Furien in Desolace gehört, der nach gleichgesinnten Abenteurern sucht. Vielleicht solltet Ihr ihn aufsuchen.\n\nLebt wohl, <Freund/Freundin>, ich werde Euch nie vergessen.", sourceObjective = "Sprecht mit Furien in Tethris Aran in Desolace.", completion = "<Furien stöhnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26135] = { id = 26135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Aufstieg aus der Tiefe", description = "Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?\n\nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.\n\nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.", sourceObjective = "Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel'Dormir benutzt.", completion = "Diener des alten Gottes? Dann haben sich zwei sehr gefährliche Feinde miteinander verbündet. Vielleicht ist es doch nicht so abwegig, dass sie den Gezeitenjäger töten können.\n\n{name}, das dürfen wir nicht zulassen. Wenn Azshara den Gezeitenjäger besiegt und seine Macht an sich reißt, kann wahrscheinlich keiner auf den Meeren gegen sie bestehen.\n\nWenigstens ist der erste Schritt eindeutig. Wir müssen dieses Untier vernichten, das unsere Schiffe zerstört hat. Unsere Marine war mutig genug, eine neue Flotte hierher zu bringen. Vielleicht haben sie ja einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26137] = { id = 26137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach den Jungs", description = "Ihr habt sicher gesehen, wie stark der Loch mittlerweile geschädigt ist. Die Schäden dehnen sich leider sogar noch weiter aus. Das ganze Wasser musste ja irgendwo hin, und es floss hinunter ins Sumpfland.\n\nDa unten unterstützen uns viele mutige Zwerge. Sie brauchen Vorräte. Aus diesem Grund habe ich zwei meiner Gebirgsjäger mit einem Fass voller Bier auf den Weg ins Sumpfland geschickt.\n\nSeit sie die Straße nach Dun Algaz erreicht haben, gab es keine Nachricht mehr von ihnen. Würdet Ihr nachsehen, ob es ihnen gut geht?", sourceObjective = "Reist ins Sumpfland und sprecht mit Gebirgsjäger Rharen nahe Dun Algaz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26138] = { id = 26138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ferilon Laubkind", description = "Eine Gruppe von Nachtelfen hat sich im Sumpfland niedergelassen. Ein paar von ihnen sind aus Kalimdor eingetroffen, um das Land hier zu untersuchen, sich die Pflanzen anzusehen und all so etwas.\n\nEiner der Druiden - er heißt Ferilon - kam hier vor einer Weile vorbei. Er war so nett, uns mit den Raptoren zu helfen und erwähnte, dass er Leute braucht, die ihn bei seinen Aufgaben unterstützen.\n\nWenn Ihr Zeit habt, könntet Ihr ihn an einem Ort im Nordosten namens Hain des Sumpfhüters aufsuchen.", sourceObjective = "Findet Ferilon Laubkind im Hain des Sumpfhüters.", sourceObjectiveStatus = "unverified-source-field" }
quests[26139] = { id = 26139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Arathi", description = "Geht vor und warnt die andere Seite des Übergangs, {name}.\n\nHinter der Brücke im Norden werdet Ihr die Zuflucht finden, die Festung der Allianz in Arathi. Sagt Hauptmann Nials, er solle sich vor den Hundesöhnen des Schattenhammers in Acht nehmen.", sourceObjective = "Reist ins Arathihochland und sprecht mit Hauptmann Nials in der Zuflucht.", completion = "Ich sollte Thargas wohl dafür danken, dass er mir einen so mutigen Helden geschickt hat.\n\nVielleicht wollte er aber auch nur alles allein aufräumen. In jedem Fall könnt Ihr hier viel für die Allianz tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26140] = { id = 26140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Ahnen reden", description = "Setzt den toten Gnadenlosen auf Euren Kopf und gebt Euch als einer ihrer Sklaven aus.\n\nBetretet L'ghorek. Kommuniziert mit dem Ahnen.", sourceObjective = "Bringt das Gehirn des Unergründlichen zu L'ghorek im Cerebrillum in L'ghorek in Vashj'ir.", progress = "ICH SPÜRE... ETWAS. KOMMT NÄHER...", completion = "WEISE VON… EUREM ERUNAK… EUCH... DAS… GEHIRN DES GESICHTSLOSEN… VERWENDEN ZU LASSEN. ICH SEHE… EUCH JETZT.\n\nICH WERDE STERBEN. ES IST NICHT… AUFZUHALTEN.\n\nABER… IHR WERDET MIR… ERST HELFEN, DIESE… PARASITEN ZU BESEITIGEN.", sourceObjectiveStatus = "unverified-source-field" }
quests[26141] = { id = 26141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runensteine der Bindung", description = "AUF DER ANDEREN… SEITE MEINES… RAUMS SIND… KANDIDATEN FÜR DEN AUFSTIEG.\n\nWIR BENÖTIGEN… IHRE RUNENSTEINE DER BINDUNG… UM EINEN... WEG ZU FINDEN... EINEN GEBUNDENEN ELEMENTAR... ZU KONTROLLIEREN.", sourceObjective = "Sammelt 7 Runensteine der Bindung.", progress = "HABT… IHR ALLES… WAS… WIR BRAUCHEN?", completion = "WIR WERDEN… DIESE… RUNENSTEINE NUTZEN… DAMIT IHR… VON EINEM… DER WASSERELEMENTARE... BESITZ ERGREIFEN KÖNNT.", sourceObjectiveStatus = "unverified-source-field" }
quests[26142] = { id = 26142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg verboten!", description = "UM IHRE… RITUALE DES AUFSTIEGS… AUFZUHALTEN… MÜSST IHR DIE… URALTEN LEITUNGEN ZERSTÖREN.\n\nSIE VERWENDEN… DIE LEITUNGEN, UM… MEINE ENERGIEN… ABZUZAPFEN UND… ASZENDENTEN ZU ERSCHAFFEN.\n\nEIN KAMPF MIT… NEPTULON IST UNVERMEIDBAR. DER SCHATTENHAMMER… DARF DIESE WESEN... NICHT HABEN.", sourceObjective = "Zerstört 5 uralte Leitungen.", completion = "IHR AUFSTIEG… IST ZU ENDE!", sourceObjectiveStatus = "unverified-source-field" }
quests[26143] = { id = 26143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was aufsteigt", description = "<Die Stimme des Ahnen drückt gegen Euren Geist.>\n\nJETZT, DA IHR… DIE ENERGIEN… DER GETREUEN… GESTOHLEN HABT… BETRETET DEN TEMPEL UND… VERNICHTET… HALLAZEAL DEN AUFGESTIEGENEN!", sourceObjective = "Tötet Hallazeal den Aufgestiegenen.", completion = "IHR HABT… MIR UND DEM… GEZEITENJÄGER EINEN… GROSSEN DIENST ERWIESEN.", sourceObjectiveStatus = "unverified-source-field" }
quests[26144] = { id = 26144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene", description = "Der Kultist des Schattenhammers hat diesen Schlüssel fallen lassen. Benutzt ihn, um die Gefangenen der Allianz in den Käfigen in L'ghorek zu befreien.\n\nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!", sourceObjective = "Rettet 5 Gefangene der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26145] = { id = 26145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung durch die Troggs", description = "{class}, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Eisenschmiede zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über die Stadt hier zu wachen und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.\n\nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir acht Troggsteinzähne als Beweis.", sourceObjective = "Sammelt 8 Troggsteinzähne.", progress = "Könnt Ihr mir acht Troggsteinzähne zeigen? Wenn nicht, dann habt Ihr immer noch etwas zu erledigen, {name}.", completion = "Ich bin ziemlich beeindruckt, {name}. Ihr habt dem Volk der Zwerge einen großen Dienst erwiesen, indem Ihr unser Land verteidigt habt. Selbst König Magni Bronzebart wäre stolz auf Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[26146] = { id = 26146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Wir müssen den Loch beschützen, {name}! Da so viele Soldaten des Königs tapfer auf entlegenen Schlachtfeldern kämpfen, wurden wir an der Heimatfront überrannt. Troggs schlüpfen aus jeder Spalte! Der Troggbefall stellt die größte Bedrohung für Eisenschmiede dar.\n\nWir brauchen Euch, <tapferer Abenteurer/tapfere Abenteurerin>, damit Ihr Euch vorwagt, um dieser Bedrohung durch die Troggs ein Ende zu bereiten. Tötet zwölf Splittersteintroggs und kommt zurück.", sourceObjective = "Tötet 12 Splittersteintroggs oder Späher der Splittersteintroggs.", completion = "Gut gemacht, {name}! Ihr habt verblüffende Tapferkeit auf dem Schlachtfeld gezeigt. Wir werden den Krieg gegen die Troggs durch solche Anstrengungen gewinnen. Ihr habt König Magni gute Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26147] = { id = 26147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größer und ekliger", description = "Die Gebirgsjäger haben mir erzählt, dass Ihr recht mutig und fähig seid, {name}. Wir brauchen <einen/eine:r> {race} wie Euch hier. Das Problem mit den Troggs wird nicht besser. Unsere Reservekräfte wurden an die Front gerufen und nun sind wir hier alleine. Mit <einem erfahrenen/einer erfahrenen:c> {class} wie Euch können wir aber sicher mehr erreichen.\n\nGeht und tötet acht Schamanen der Splittersteintroggs und acht Knochenknacker der Splittersteintroggs. Ihr könnt sie in und in der Nähe der Höhle im südlichen Teil der Berge finden.\n\nNun lasst uns sehen, ob Ihr Eurem Ruf als Trogg-Schreck gerecht werdet.", sourceObjective = "Tötet 8 Schamanen der Splittersteintroggs und 8 Knochenknacker der Splittersteintroggs.", completion = "Ich war mich sicher, als ich Euch gesehen habe, {name}: Ihr würdet Eisenschmiede stolz machen. Ihr habt unserem Volk gut gedient. Ich salutiere vor Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26148] = { id = 26148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Entscheidungsschlag", description = "Die Bestien in Loch Modan scheinen einem Häutpling namens Grawmug zu folgen. Er ist der größte aller Troggs und hält sich tief in der Dunkelheit der Höhlen nördlich von hier auf.\n\nWenn Ihr meint, Ihr seid einer solchen Aufgabe gerecht, so würde ich Euch gerne mit der Ermordung Grawmugs beauftragen.", sourceObjective = "Tötet Grawmug.", completion = "Ausgezeichnet, {name}! Ihr habt wieder Hoffnung nach Loch Modan gebracht. Durch den Tod Grawmugs haben wir bessere Aussichten darauf, die Troggs aus diesen Landen zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26149] = { id = 26149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene", description = "Der Kultist des Schattenhammers hat diesen Schlüssel fallen lassen. Benutzt ihn, um die Gefangenen der Horde in den Käfigen in L'ghorek zu befreien.\n\nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!", sourceObjective = "Rettet 5 Gefangene der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26150] = { id = 26150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei Maybell", description = "Ihr scheint mir vom hilfsbereiten Schlag zu sein, {name}. Würdet Ihr einem alten Mann einen Gefallen tun?\n\nDas letzte Mal, als ich drüben in den Weinbergen der Maclures war, habe ich Maybell in ihrer Hütte weinen hören. Wärt Ihr so nett und würdet nach ihr sehen? Ich mache mir Sorgen um sie.", sourceObjective = "Sprecht mit Maybell Maclure in den Weinbergen der Maclures in den Wäldern von Elwynn.", completion = "William hat Euch geschickt? Gesegnet sei seine Seele. Mir… mir geht es gut. Es ist nur… Nun ja…", sourceObjectiveStatus = "unverified-source-field" }
quests[26152] = { id = 26152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: James Clark", description = "Auf Geheiß der Armee von Sturmwind wurde ein Kopfgeld auf James Clark ausgesetzt.\n\nClark wird gesucht wegen Raubes, Einbruchs, Brandstiftung und Mordes. Er wird auch verdächtigt, Brackbrunns preisgekröntes Schwein Prinzessin entführt zu haben und versteckt zu halten.\n\nJames Clark wurde zuletzt auf dem Weg zum Holzfällerlager des Osttals gesehen.\n\nFührt James Clark der Gerechtigkeit zu und meldet Euch dann bei Marschall McCree im Holzfällerlager des Osttals.", sourceObjective = "Tötet James Clark und nehmt James Clarks Kopf.", progress = "Wollt Ihr ein Kopfgeld einfordern?", completion = "Und wieder wurde der Gerechtigkeit Genüge getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26153] = { id = 26153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pennys Kürbiskuchen", description = "Meine Tochter liebt Kürbispuffer, aber hier in Elwynn gab es dieses Jahr wegen des kalten Winters nur wenig Kürbisse. Ich habe aber von einem Kürbisfeld bei Sturmwind gehört, auf dem die Früchte nun reif sein sollen. Erntet für mich ein paar reife Kürbisse und ich werde Euch meinen Dank beweisen.", sourceObjective = "Sammelt 6 Sturmwindkürbisse und bringt sie Robby Flay in Sturmwind.", progress = "Habt Ihr die Kürbisse geerntet?", completion = "Gute Arbeit, {name}! Penny wird morgen zum Frühstück eine tolle Überraschung bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26154] = { id = 26154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenkammerjäger", description = "NUN… NEHMT DEN… ABGESTIMMTEN RUNENSTEIN… UND BENUTZT IHN… UM VON EINEM… GEBUNDENEN STROM… IM MITTLEREN TEMPEL… BESITZ ZU ERGREIFEN. SIE WERDEN… EUCH… IGNORIEREN. KEINER WIRD… EUCH BEMERKEN.\n\nNUTZT... DIE MACHT DES ELEMENTARS… UM ZWIELICHTVEREHRER... UND IHRE GESICHTSLOSEN AUFSEHER... ZU TÖTEN.", sourceObjective = "Ergreift Besitz von einem gebundenen Strom und tötet dann 50 Zwielichtverehrer und 10 gesichtslose Aufseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[26157] = { id = 26157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kasim Sharim", description = "Ich möchte, dass Ihr eine Nachricht für mich überbringt.\n\nKasim Sharim ist ein alter Blutmagier, der viel über die Dämonen in den Verwüsteten Landen weiß. Man sieht es ihm zwar nicht an, aber er ist recht alt und sehr mächtig... aber auch ein wenig exzentrisch. In letzter Zeit hält er sich meistens im hinteren Teil der Schlangenschlinge auf, einer Höhle in der Nähe des Ortes, an dem ihr die Kultisten getötet habt.\n\nBitte überbringt ihm diese Nachricht. Er wird ihre Bedeutung verstehen.", sourceObjective = "Meldet Euch bei Kasim Sharim im hinteren Teil der Schlangenschlinge in den Verwüsteten Landen.", progress = "Ich kenne Euch nicht.", completion = "Hah! Ihr Einfaltspinsel aus Nethergarde seid immer zwei Schritte hinter mir, dabei bin ich längst nicht so schnell wie früher.\n\nIch brauche Mahars Notiz nicht. Ich weiß auch so, was vorgeht. Was glaubt Ihr, weshalb ich mich so tief in eine Höhle zurückgezogen habe? Einen starken {race} wie Euch kann ich allerdings gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26158] = { id = 26158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmt den Blutstein ab", description = "Haben die Kämpfe auf dem Weg durch die Höhle Spaß gemacht? Zugegebenermaßen habe ich nicht die... praktischste Stelle für meine Studien ausgesucht, vor allem nicht für vorbeiziehende <Abenteurer/Abenteuerinnen>, die nach Belieben kommen und gehen wollen.\n\nAllerdings kann ich Euch an meine Blutsteinteleporter anpassen. Legt einfach Eure Hände auf den Stein in der hinteren Ecke, dann werdet Ihr vor die Höhle versetzt. Benutzt den Stein draußen, um wieder hinein zu kommen!", sourceObjective = "Stellt euch auf die Blutsteinteleporter in der Schlangenschlinge ein.", completion = "Hervorragend! Ihr habt die einfachste aller Aufgaben bewältigt, ohne zu sterben. Das hätten wir erledigt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26159] = { id = 26159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Wie jeder gute Blutmagier wirke ich meine Magie mit Blut. Jedes Blut ist anders. In den Verwüsteten Landen gibt es mehrere nützliche Geschmacksrichtungen, wenn man weiß, wo man suchen muss.\n\nFür unsere Zwecke? Basilisken und Hyänen zu gleichen Teilen. Wir werden viel Blut brauchen. Geht nach Westen ins Herz der Verwüsteten Lande. Und vergesst nicht, den Teleporter zu benutzen!", sourceObjective = "Beschafft 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.", progress = "Habt Ihr es?", completion = "<Kasim betrachtet das Blut gierig.>\n\nMehr als genug und immer noch warm! Dann lasst uns das Ritual beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26160] = { id = 26160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutritual", description = "Ihr wollt wahrscheinlich wissen, was wir tun. Hier ist die Kurzfassung - eine Fassung, in der ich Experte bin:\n\nDie Kultisten der Schattenanbeter wollen den Dämon Razelikh beschwören und in die Verwüsteten Lande holen. Das können wir nicht zulassen. Deshalb werden wir ihn selbst beschwören und umbringen. Das klingt leichter als es ist...\n\nLasst mich wissen, wenn Ihr für das Blutritual bereit seid und tretet dann zurück.", sourceObjective = "Sprecht mit Kasim Sharim, um das Blutritual einzuleiten.", completion = "Das Blutritual war ein Erfolg. Ich weiß genau, wohin wir als nächstes gehen müssen.\n\nTut mir Leid, falsche Formulierung. Ich wollte sagen, ich weiß, wohin IHR als nächstes gehen müsst...", sourceObjectiveStatus = "unverified-source-field" }
quests[26161] = { id = 26161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht irgendeine Leiche", description = "Wir brauchen Loramus Thalipedes, den Dämonenjäger. Er kennt Razelikhs wahren Namen und wie Ihr wisst, braucht man den Namen eines Dämons, um Macht über ihn zu gewinnen. Das Problem ist nur, dass Loramus getötet und seine Leiche zerrissen wurde.\n\nWenn Ihr mir die Teile bringt, lässt sich noch etwas ausrichten. Alle drei Teile befinden sich im Westen... die Schreckensfelsoger verstecken sie in ihren Höhlen. Beeilt Euch, denn ebenso wie Grimeo, schuldet mir auch Loramus etwas...", sourceObjective = "Findet Loramus' Kopf, Loramus' Torso und Loramus' Beine.", progress = "Vertraut mir... was Loramus zugestoßen ist, lässt sich richten. Die Grenzen der Blutmagie sind noch undefiniert.", completion = "Verstehe... ja, damit kann ich arbeiten.\n\n<Kasim betrachtet den Kopf des Nachtelfen.>\n\nLoramus Thalipedes, Dämonenjäger. Ich freue mich auf unser Wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26162] = { id = 26162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar der Stürme", description = "Auf den Klippen westlich von hier steht ein mächtiger Altar. Ein mächtiger, DÄMONISCHER Altar, der von Kultisten bewacht wird, aber trotzdem mächtig ist. Wenn Ihr ihn erreichen könnt, dann wäret Ihr in der Lage, Loramus zu uns zurückzubringen.\n\nDer Altar wird sich Euch wahrscheinlich widersetzen, deshalb müsst Ihr Loramus' Leichnam bis zur Vollendung des Rituals beschützen. Bringt den Dämonenjäger anschließend zu mir zurück.", sourceObjective = "Bringt Loramus' Leichnam zum Altar der Stürme und beschützt ihn während des Rituals.", completion = "Ihr... Ihr Narr! Was habt Ihr getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[26163] = { id = 26163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit ist knapp", description = "Razelikh will in die Verwüsteten Lande zurückkehren und Azeroth mit seinen Dämonen überrennen. Er bereitet bereits die Beschwörung der Legionen vor, die uns vernichten sollen. Mit diesen drei Amuletten können wir ihn zwar beschwören... aber nicht zerstören.\n\n<Der Gnom zeichnet rasch eine Rune in die Luft und reicht sie Euch.>\n\nBringt dies zu Grimeo am Dunklen Portal im Südosten. Er wird Euch führen. Beeilt Euch! Eure Zeit ist knapp bemessen! So wie meine Größe!", sourceObjective = "Bringt die disharmonische Rune zu Behüter Grimeo am Dunklen Portal in den Verwüsteten Landen.", progress = "Kenne ich Euch, guter {race}?", completion = "Nein, nein, nein... nicht wieder Kasim! Das ist Irrsinn!\n\nBitte bleibt ruhig. Wisst Ihr, wie schnell man mich aus der Wache werfen wird, wenn mein Kommandant erfährt, dass ich immer noch für den Kurzen arbeite?\n\n<Ihr gebt Grimeo die Rune. Er presst sie gegen seine Brust, schließt die Augen und seufzt.>\n\nWie ich sehe, sagt Ihr die Wahrheit. Lasst uns rasch beginnen, damit es noch rascher vorüber ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26164] = { id = 26164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verkohlte Granit des Dunklen Portals", description = "Kasim möchte, dass Ihr Granitsplitter von den Felsen rund um das Dunkle Portal sammelt. Ich weiß nicht, was er mit den Felsen vorhat, aber ich habe einen Verdacht und der ist nicht angenehm.\n\nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal", sourceObjective = "Besorgt 24 verkohlte Granitsplitter.", progress = "Bitte sprecht leise.", completion = "Hoffentlich ist es das, was der Gnom wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26165] = { id = 26165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das abscheuliche Blut der Dämonen", description = "Sharim will Dämonenblut. Für mich persönlich sieht das Zeug nicht einmal aus wie Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.\n\nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt, in reichlichen Mengen.", sourceObjective = "Besorgt 7 Flaschen mit abscheulichem Dämonenblut.", progress = "Ihh, was stinkt hier so? Seid Ihr das, oder das Blut?", completion = "Ihr habt ohne jeden Zweifel Dämonenblut gefunden.\n\nVon Kasims Bitte einmal abgesehen, bin ich sicher, dass mein Wachkommandant für Eure Bemühungen sehr dankbar ist. Sie haben schon seit einiger Zeit Schwierigkeiten, mit diesen Ablenkungen der Dämonen zurechtzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26166] = { id = 26166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserung des Steins", description = "<Grimeo packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>\n\nDas ist alles, was der Gnom von uns verlangt hat. Wenn Ihr ihn seht, sagt ihm bitte, dass meine Schuld mit dieser Aufgabe beglichen ist. Ich werde seine Bitten nicht länger erfüllen.", sourceObjective = "Bringt Grimeos Paket zu Kasim Sharim in der Schlangenschlinge in den Verwüsteten Landen.", progress = "Ihr seid zurückgekehrt, {class}.", completion = "Das wird genügen. Wenn Ihr Grimeo noch einmal seht, sagt ihm, dass er befriedigend gearbeitet hat. Jedoch ist seine Schuld noch nicht getilgt. Ich werde mich an die Arbeit machen und das Steinmesser des Versiegelns herstellen. Jetzt sind Fragen unnötig. Alles wird sich zu seiner Zeit klären.\n\nSolange ich arbeite, habe ich eine andere Aufgabe, die Ihr erledigen könnt.\n\nWas seht Ihr mich so böse an? Diese Aufgabe wird Euch Spaß machen... es geht um das Sammeln von Körperteilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26167] = { id = 26167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Allistarj", description = "Um unseren Dämon zu beschwören, brauchen wir drei Amulette. Das erste ist das Amulett von Allistarj.\n\nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in dieser Höhle eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.\n\n<Kasim konzentriert sich einen Moment.>\n\nDas Amulett befindet sich nahe des Eingangs. Ich würde vorschlagen, den Teleporter zu benutzen.", sourceObjective = "Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.", progress = "Allistarj hat einen Teil seiner selbst in dem Amulett hinterlassen. Sogar jetzt kann ich seine Bosheit spüren.", completion = "<Kasim untersucht das Amulett.>\n\nEr war ein Erzmagier, das spüre ich. Ich werde das Amulett für Euch aufbewahren, während Ihr die anderen sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26168] = { id = 26168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Sevine", description = "Das zweite Amulett, Sevines Amulett, befindet sich weit im Süden in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.\n\nBringt mir ihr Amulett, zusammen mit dem Rest.", sourceObjective = "Besorgt das Amulett von Sevine von Salzflopper nahe der Havarieküste in den Verwüsteten Landen.", progress = "Sevines Amulett - zusammen mit den anderen können wir den Entweiher beschwören.", completion = "<Kasim wiegt das Amulett in der Hand.>\n\nEin Hexenmeister... und zwar ein mächtiger. Ich werde das hier behalten, bis die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26169] = { id = 26169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Grol", description = "Grol... der Oger.\n\n<Kasim lacht.>\n\nGrols Leichnam ruht wohl nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.", sourceObjective = "Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.", progress = "Das dritte Amulett von Razelikhs drittem Hauptmann.", completion = "<Kasim umklammert das dritte Amulett.>\n\nEr war ein mächtiger Krieger. Ich werde das Amulett behalten, bis wir bereit sind, fortzufahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26170] = { id = 26170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Ritual", description = "Das Messer ist fertig. Loramus ist anwesend und weiß, was er zu tun hat. Ich werde nun die drei Amulette nehmen und ihre Verzauberung nutzen, um Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, zu verschaffen.\n\nIch bin bereit, dieses Ritual an Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr beide ebenfalls bereit seid.", sourceObjective = "Sprecht mit Kasim Sharim, um an seinem Ritual teilzunehmen.", completion = "Anscheinend sind wir jetzt bereit, unserem Dämon entgegenzutreten, {name}. Wir haben den Segen des Amuletts, wir haben das Steinmesser und ich allein weiß den wahren Namen des Dämons: Rakh'likh. Zusammen könnte das genügen, den Entweiher zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26171] = { id = 26171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid Rakh'likh, Dämon", description = "<Held/Heldin>, hört gut zu.\n\nZunächst müssen wir nach Nordwesten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe begleiten. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.\n\nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.\n\nWenn wir Erfolg haben, sprecht mit Grimeo, dem Draenei.", sourceObjective = "Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.", completion = "Loramus wiedererweckt? Und dann setzte er den Dämon in seinem eigenen Körper fest.. beim Licht...\n\nIch verstehe. Also hatte Kasim das die ganze Zeit so geplant. Ich hatte den richtigen Verdacht, aber ich denke, ich wollte es nicht glauben.\n\nAh, noch eines! Kasim hat mir eine letzte Anweisung in seiner Rune übermittelt. Anfangs verstand ich sie nicht, aber nach den heutigen Ereignissen ergibt sie wesentlich mehr Sinn:\n\nEr sagte mir, ich solle Euch eins hiervon auswählen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26172] = { id = 26172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Blutmagier müssen essen", description = "Entgegen der landläufigen Vorstellung trinken uralte und mächtige Blutmagier KEIN Blut. Wir essen normale Speisen so wie jeder andere auch - etwas, was in der hintersten Ecke einer feindlichen Kultistenfeste schwer zu bekommen ist.\n\nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind eine praktische Speise, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und meine schwindenden Nahrungsvorräte wieder aufstocken?", sourceObjective = "Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.", progress = "Ich bin so hungrig! Wenn Ihr Euch nicht beeilt, sehe ich mich doch noch gezwungen, meine Reagenzien zu trinken.", completion = "Die sind perfekt, {name}. Ich werde in den nächsten Tagen gut zu essen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26173] = { id = 26173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückendeckung", description = "Der einzige Grund, warum Ihr mich neben Soldaten der Horde stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - wenn auch knapp. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...\n\nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.", sourceObjective = "Tötet Jarroc Flügelriss, Shahandana und Gomegaz.", completion = "Wir wissen Eure Arbeit zu schätzen, Soldat.\n\n<Der Kommandant beugt sich vor und beginnt zu flüstern:>\n\n{race}... Wenn Ihr noch interessiert seid, ich habe da eine kleine Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[26174] = { id = 26174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhut", description = "<Wachkommandant Reldorn Netherschwund schlägt einen verschwörerischen Ton an.>\n\nIch habe Befehle von... oben... für die Ihr bestens geeignet seid. Ich habe gesehen, dass die Horde regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...", sourceObjective = "Untersucht die Pläne der Horde am Dunklen Portal, ohne erwischt zu werden.", completion = "Ihr seid sicher, dass Euch niemand beobachtet hat? Gut.\n\n<Netherschwund hört aufmerksam Eurem Bericht über die Informationen, die Ihr gesehen habt, zu.>\n\nHmpf... ziemlich harmloses Zeugs. Entweder ist die Horde dumm genug, NICHTS gegen uns unternehmen zu wollen... oder sie verstecken ihre Informationen besser, als ich erwartet habe. Wie auch immer - gut gemacht, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26175] = { id = 26175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surwich", description = "Abgesehen von dem, was Ihr gesehen habt, ist das Portal überraschend ruhig. Leider kann ich Euch kaum noch Arbeit geben.\n\nWenn Ihr nach Ärger sucht, könntet Ihr es im Fischerdorf der Gilneer im Südwesten versuchen. Surwich, so heißt es, glaube ich.\n\nIch weiß, dass wir eigentlich mit den Gilneern befreundet sein sollten, aber mal ehrlich? Worgen? Es fiel mir schon schwer, mich an die Draenei zu gewöhnen.", sourceObjective = "Meldet Euch bei Bürgermeister Carl Connisport in Surwich in den Verwüsteten Landen.", completion = "Willkommen in Surwich, {race}. Seht Euch ruhig um.", sourceObjectiveStatus = "unverified-source-field" }
quests[26176] = { id = 26176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Thelsamar", description = "Ihr habt uns hier sehr geholfen. Falls Ihr aufbrechen wollt, würde ich Euch gerne bitten, diesen Statusbericht nach Thelsamar zu bringen.\n\nFolgt der Straße in Richtung Norden und Ihr könnt es nicht verfehlen. Der Statusbericht muss zu Gebirgsjäger Kadrell.", sourceObjective = "Bringt den Statusbericht von Hauptmann Rugelfuß zu Gebirgsjäger Kadrell in Thelsamar.", progress = "Wie kann ich Euch helfen?", completion = "Gut, dass Ihr Euch um die Troggs gekümmert habt. Dann lasst uns mal den Bericht ansehen und...\n\n...ist das ein Bierfleck?", sourceObjectiveStatus = "unverified-source-field" }
quests[26177] = { id = 26177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lust auf Krebs?", description = "Frische Krabbenbeine waren schon immer eine der Lieblingsspeisen des Königs. Wir hatten in den letzten Wochen viel Erfolg beim Krebsfangen in den Kanälen. Könnt Ihr mir helfen und ein paar für mich fangen? Sie müssen lebendig gefangen werden, tot nützen sie mir nichts - für den König ist nur der frischeste Fang gut genug.", sourceObjective = "Sammelt 6 Kanalkrebse und bringt sie zu Robby Flay in Sturmwind.", progress = "Ihr müsst schnelle Hände haben! Ich kann kaum glauben, dass Ihr alle Krebse in so kurzer Zeit fangen konntet!", completion = "Diese Krebse sehen toll aus! Ich werde sie säubern und sicherstellen, dass der König von Eurer Hilfe erfährt. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[26178] = { id = 26178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukunftsplanungen", description = "Um unser Überleben zu sichern, müssen wir entschlossen gegen die Wolvar vorgehen. Ich mache mir jedoch Sorgen, dass wir in unserem Eifer zu viele von ihnen erschlagen werden.\n\nDie Schneewehenwolvar haben genauso wie wir das Recht zu überleben - also werden wir beide dafür sorgen, dass sie dieses Recht auch bekommen.\n\nWenn er es nicht schon längst getan hat, dann wird Euch Ältester Ko'nani darum bitten, mit den Wolvar fertig zu werden. Und aus diesem Grund möchte ich auch, dass Ihr ihre Jungen einfangt und sie zu mir bringt, wenn Ihr Euch auf der Lichtung im Norden befindet.", sourceObjective = "Sammelt 12 Schneewehenwelpen und liefert sie anschließend bei Fallensteller Mau'i im Hafen Moa'ki ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[26179] = { id = 26179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Venture Company", description = "Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.\n\nGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der Überfallenen Karawane und schickt ihnen eine Nachricht.", sourceObjective = "Tötet 7 Tagelöhner der Venture Co. für Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe.", completion = "Ich glaube nicht, dass man dieses Signal fehldeuten oder ignorieren kann, oder? Die Venture Company wird die {race} nicht mehr auf die leichte Schulter nehmen oder so arrogant sein zu glauben, dass wir ihren Diebstahl der natürlichen Rohstoffe um uns herum einfach so widerstandslos hinnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26180] = { id = 26180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsteher Zischelspross", description = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben.\n\nIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Zischelspross; Ihr findet ihn in der Mine der Venture Co. östlich der Überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.", sourceObjective = "Tötet Vorsteher Zischelspross und nehmt sein Klemmbrett an Euch.", progress = "Bei dem Gedanken an die Abscheulichkeiten, die die Venture Company im Namen des Gewinns geplant haben, koche ich fast über vor Ärger.", completion = "Die Nachricht vom Tod des Bösewichts Zischelspross hat meine Wut etwas abgekühlt. Ich werde seine persönlichen Habseligkeiten durchsehen, um herauszufinden, ob es weitere Informationen über die Zukunftspläne der Venture Company gibt. Vielen Dank für Eure Bemühungen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26181] = { id = 26181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Dämmerbucht", description = "IHR MÜSST ZURÜCK… ZUR… DÄMMERBUCHT. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.\n\nICH STERBE JETZT...", sourceObjective = "Sprecht mit Erunak Steinsprecher in der Dämmerbucht in Vashj'ir.", completion = "Willkommen zurück, {class}.\n\nIch habe gespürt, wie L'ghorek starb. Es ist eine Schande, dass so ein fantastisches Wesen nicht mehr unter uns weilt.\n\nWenn wir Neptulon nicht unterstützen, wird uns alle das gleiche Schicksal ereilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26182] = { id = 26182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Schattenhöhle", description = "IHR MÜSST ZURÜCK… ZUR… SCHATTENHÖHLE. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.\n\nICH STERBE JETZT...", sourceObjective = "Sprecht mit Erunak Steinsprecher in der Schattenhöhle in Vashj'ir.", completion = "Willkommen zurück, {class}.\n\nIch habe gespürt, wie L'ghorek starb. Es ist eine Schande, dass so ein fantastisches Wesen nicht mehr unter uns weilt.\n\nWenn wir Neptulon nicht unterstützen, wird uns alle das gleiche Schicksal ereilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26183] = { id = 26183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Königs Apfelwein", description = "Ich stehe für immer in der Schuld des Königs. Für alles, was er für uns getan hat. Ich kann ihm nicht viel anbieten, aber sein Lieblingsgetränk kann ich ihm brauen! Glücklicherweise wachsen die Zutaten für dieses köstliche Getränk hier in Sturmwind. In jedem Distrikt stehen Apfelbäume. Die Bäume sind zu hoch, um die Äpfel zu pflücken, aber die, die auf den Boden gefallen sind kann man leicht aufsammeln.", sourceObjective = "Sammelt 12 saftige Äpfel und bringt sie zu Robby Flay in Sturmwind.", progress = "Habt Ihr genug saftige Äpfel finden können?", completion = "Das sind gute Äpfel, {name}. Ich werde mich gleich daran machen, den Apfelwein zu brauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26184] = { id = 26184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurmdorns Traum", description = "Es wird Euch nicht überraschen, dass die meisten Einwohner von Surwich nicht wegen der angenehmen Atmosphäre in die Verwüsteten Lande gekommen sind. Sie kamen, weil sie dem Traum eines idealistischen Druiden folgten: Marl Wurmdorn. Wurmdorn glaubte, dass die Faulende Narbe geheilt werden könnte und versuchte, sie wachsen zu lassen.\n\nEr hat sich wohl geirrt. Er ließ seinen Wald wachsen, aber das Land wird immer noch von Dämonen heimgesucht und sein großer Baum ist verwachsen und knorrig.\n\nTrotzdem hoffe ich noch. Wenn wir uns in den Besudelten Wald begeben und einen Teil der Besudelung entfernen könnten...", sourceObjective = "Tötet 5 Zerstörer der Verdammniswache, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.", completion = "Ihr sagt, all die Dämonen hätten den Baum angebetet?\n\n<Der Bürgermeister seufzt.>\n\nWie ich befürchtet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26185] = { id = 26185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat vom Zirkel des Cenarius", description = "Ich glaube, dass die Besudelung der Verwüsteten Lande ihren Einfluss auf meinen Freund Wurmdorn ausgeweitet hat. Sein Experiment ist gescheitert und sein großer Baum dient nur noch den Dämonen als Versammlungsort.\n\nDer Baum muss fallen und Wurmdorn mit ihm. Sprecht mit der cenarischen Beobachterin auf der anderen Seite des Orts. Sie sollte wissen, was als nächstes zu tun ist.\n\n{name}: Die Einwohner von Surwich dürfen nichts von unseren Plänen erfahren. Ihre Stimmung ist schon schlecht genug.", sourceObjective = "Meldet Euch bei der cenarischen Beobachterin Shayana in Surwich in den Verwüsteten Landen.", completion = "Es überrascht mich zwar, dass Connisport gewillt ist, seinen Plan umzusetzen, aber es erleichtert mich auch. Ich habe gesehen, wie sich die Dämonen um Maldraz versammeln. Ich teile seine Furcht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26186] = { id = 26186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonisches Gefäß", description = "Wir müssen Wurmdorns Aufmerksamkeit erregen. Wir brauchen etwas, das ihn aus seiner Trance holt. Etwas, das garantiert funktioniert.\n\nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen worden. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal, ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.", sourceObjective = "Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.", progress = "Shayanas Plan ist gut. Habt Ihr das Gefäß, {name}?", completion = "<Bürgermeister Carl Connisport blickt voller Argwohn auf das Gerät, dass Ihr zusammengesetzt hab.>\n\nNun gut, {name}. Wir haben, was wir brauchen, um Marls Trance zu durchbrechen und sowohl ihm als auch seinem Experiment ein Ende zu bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26187] = { id = 26187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Marl Wurmdorn", description = "Wenn sich herumspricht, was wir getan haben... kann niemand sagen, wie die Bürger von Surwich reagieren werden. Sie klammern sich an Wurmdorns Traum...\n\n...aber trotzdem müssen wir es tun. Nehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.", sourceObjective = "Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.", completion = "Danke, {name}. Ich und die Bürger von Surwich stehen in Eurer Schuld.\n\nNehmt ruhig eins von diesen hier. Wir haben zwar nicht viel, aber wir belohnen gern die, die uns beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26188] = { id = 26188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazzranach", description = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranach. Er erzählte mir von seinen dämonischen roten Augen, seinen rasiermesserscharfen Krallen und seinem giftigen Biss.\n\nWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend wie ihn mein Großvater beschrieben hatte. Ich habe alle Zutaten für das Gegengift, das ich für meine Heilung benötige, zusammen... bis auf einen Knochen eines Flachlandpumas.\n\nIch werde von Minute zu Minute schwächer... bitte helft mir.", sourceObjective = "Bringt einen Knochen eines Flachlandpumas zu Maur Regenrufer im Dorf der Bluthufe.", progress = "Mein Fieber wird immer schlimmer und ich merke, wie ich langsam in schreckliche Alpträume abgleite... Ich hätte wissen müssen, dass ich keine Bestie bewältigen kann, die selbst mein Großvater nicht besiegen konnte...\n\nHabt Ihr die Zutaten für die Arznei? Ich fürchte, wenn ich die Infektion nicht bald säubere, wird das mein Ende sein.", completion = "Ah, danke, {name}. Mit den Dingen, die Ihr mir gebracht habt, kann ich die Arznei herstellen, mit der ich die Ausbreitung der Infektion unterbinden und die Krankheit endgültig heilen kann. Ich schulde Euch meinen lebenslangen Dank.\n\nAber ich werde nie diesen schrillen Schrei vergessen, als sich Mazzranach auf mich stürzte, diese Explosion von Farben, als sich sein Schnabel senkte...\n\nSeid vorsichtig auf Euren Reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26189] = { id = 26189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grollhauerbedrohung", description = "Als wir uns hier oben hin zurückzogen, um den Raptoren zu entgehen, landeten wir genau neben jeder Menge Drachenmalorcs!\n\nIn Menethil habe ich Geschichten gehört - dass die Orcs des Drachenmals noch barbarischer als andere Orcs sind, dass sie schwarze Drachen mit bloßen Händen erwürgen... Ich weiß nicht, was davon stimmt, aber wir können sie nicht in den Hügeln sitzen lassen.\n\nIhr habt genug Mut dafür, {name}. Geht nach Osten zum Lager der Grollhauer, kümmert Euch um diese Orcs und vor allem um ihren Anführer!", sourceObjective = "Tötet Gorfax Grollhauer und 16 Orcs des Drachenmals im Lager der Grollhauer.", completion = "Schön, dass Ihr heil zurückgekehrt seid, {name}! Ihr seid ganz schön hart.\n\nIch werde Hauptmann Starkfaust erzählen, wie Ihr die Orcs erledigt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26190] = { id = 26190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fischerschmaus", description = "Wenn der König ein Lieblingsessen hat, dann ist es frischer Wels. Wels ist leicht zuzubereiten aber schwer zu fangen. Genau - hier kommt Ihr ins Spiel. Wir haben in Sturmwind viele gigantische Welse und der Wettbewerb, sie zu fangen, ist sehr intensiv, um es vage zu formulieren. Findet für mich einen Weg, diese feinen Welse für den König zu erhaschen. Ihr werdet am Ufer des Kanals überall in der Stadt Fischer finden. Den Rest des Planes findet Ihr sicherlich selber heraus.", sourceObjective = "Bringt 5 gigantische Welse in Euren Besitz und bringt sie zu Robby Flay in Sturmwind.", progress = "Konntet Ihr den Fisch klauen?", completion = "Ich danke Euch, {name}. Ich werde die Welse sofort für den König entschuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26191] = { id = 26191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel unserer Bemühungen", sourceObjective = "Jeden Tag treffen weitere Krieger unter dem Befehl Azsharas ein. Bald wird Neptulon der Gezeitenjäger von unseren Vorbereitungen erfahren, aber dann ist es zu spät um aufzuhalten, was wir in Bewegung gesetzt haben. Wir werden zu viele und unsere Verbündeten zu mächtig sein. Der Sieg ist nur eine Frage der Zeit.\n\nIm Namen Azsharas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26192] = { id = 26192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Waisen mögen Kekse!", description = "Die Waisenkinder Sturmwinds werden oft vergessen, aber nicht heute. Der König hat nach einer Sonderlieferung Kekse gefragt, die umgehend zum Waisenhaus geschickt werden soll. Mit der letzten Ladung war ich fast fertig, aber dann ging mir der Puderzucker aus. Könnt Ihr schnell los und mir welchen besorgen? Jeder Gemischtwarenladen in der Stadt oder auch die Gasthäuser sollten welchen haben.", sourceObjective = "Bringt 4 Säcke Puderzucker zu Robby Flay in Sturmwind.", progress = "Konntet Ihr Puderzucker finden?", completion = "Ja, das sollte genug sein, {name}. Ich freue mich schon auf die glücklichen Gesichter der Waisenkinder.", sourceObjectiveStatus = "unverified-source-field" }
quests[26193] = { id = 26193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Abgrunds", description = "Das Flüstern der Elemente summt in meinen Gedanken, {name}…\n\nDer Thron der Gezeiten wird belagert!\n\nWir dürfen nicht tatenlos zusehen, wie die Naga Neptulons Reich bedrohen.\n\nMacht Euch bereit! Mit diesem Unterseeboot und seiner Bewaffnung können wir vielleicht etwas ausrichten.\n\nSprecht mit mir, wenn Ihr bereit seid, in den Kampf zu ziehen.", sourceObjective = "Sprecht mit Erunak in der Dämmerbucht, um Euch dem Kampf um den Wirbelnden Abgrund anzuschließen.", completion = "NEIN!\n\nEs ist NICHT vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[26194] = { id = 26194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Abgrunds", description = "Das Flüstern der Elemente summt in meinen Gedanken, {name}…\n\nDer Thron der Gezeiten wird belagert!\n\nWir dürfen nicht tatenlos zusehen, wie die Naga Neptulons Reich bedrohen.\n\nMacht Euch bereit! Mit diesem Unterseeboot und seiner Bewaffnung können wir vielleicht etwas ausrichten.\n\nSprecht mit mir, wenn Ihr bereit seid, in den Kampf zu ziehen.", sourceObjective = "Sprecht mit Erunak in der Schattenhöhle, um Euch dem Kampf um den Wirbelnden Abgrund anzuschließen.", completion = "Sie denken vielleicht, sie hätten gewonnen, aber meine Axt und ich sind da anderer Meinung!", sourceObjectiveStatus = "unverified-source-field" }
quests[26195] = { id = 26195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hütet den Sumpfhüter", description = "Der Sumpfhüter war eine lokale Legende. Viele hielten ihn für einen Mythos... den Pflanzenmann, Beschützer des Sumpflands. Die Nachtelfen kamen ausschließlich hierher, um ihn zu finden. Als ihnen das gelang, ließen sie sich im Osten nieder.\n\nEs gibt dort einen ganzen Hain, der über den Sumpfhüter wachen soll, und ich habe gehört, dass er den Nachtelfen Probleme macht. Er ist wütend über die Überflutungen und die Schädigung des Landes.\n\nDas sind gute Elfen. Sie könnten Hilfe von jemandem wie Euch brauchen. Wenn sich die Gelegenheit ergibt, dann sagt dem Anführer der Druiden, was Ihr hier getan habt.", sourceObjective = "Sprecht mit Ferilon Laubkind im Hain des Sumpfhüters im Sumpfland.", completion = "Willkommen im Hain des Sumpfhüters, {class}. Es freut mich, dass Whelgar von uns erzählt hat.\n\nFür Eure Unterstützung wäre ich Euch sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26196] = { id = 26196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langzopf der Grimmige", description = "Die Zwerge von Dun Modr kämpfen Tag und Nacht gegen die Dunkeleisenzwerge, die in ihre alte Heimat eingedrungen sind. Wir können es zwar unseren Wächtern nicht erlauben, ihr Leben für sie zu riskieren, aber wir schicken ihnen dringend benötigte Vorräte, damit sie ihre Wache fortsetzen können.\n\nWenn es geht, könntet Ihr Langzopf dem Grimmigen nördlich von hier dieses Paket bringen? Seine Leute können den Inhalt sicherlich gut gebrauchen.", sourceObjective = "Bringt Ferilons Überlebenspaket zu Langzopf dem Grimmigen in Dun Modr.", progress = "Oh, was habt Ihr da für mich?", completion = "Vorräte von Ferilon? Guter Mann.\n\nWir haben genug zu essen, aber uns gehen die Kugeln aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[26197] = { id = 26197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nBipsi Frostschleuder wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch im Erdgeschoss des großen Gebäudes im Nordosten.", sourceObjective = "Trefft Bipsi Frostschleuder in Neu-Tüftlerstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26198] = { id = 26198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Magiers", description = "Ich möchte Euch eine einfache Technik zeigen. Sie erlaubt es Euch, Ausstöße arkaner Energie zu fokussieren, zu kanalisieren und einem Feind entgegenzuschleudern.\n\nMit wachsender Macht werdet Ihr lernen, wie man jeder Salve mehr und mehr Geschosse hinzufügt.\n\nFindet eine der Trainingsattrappenanlagen in der Mitte der Stadt. Ihr werdet nicht gleich in der Lage sein, arkane Geschosse zu zaubern. Zuerst müsst Ihr andere Zauber auf die Attrappe wirken, bis Ihr die Gelegenheit geschaffen habt, arkane Geschosse zu verwenden. Versucht es selbst einmal.", sourceObjective = "Sprecht mit Bipsi Frostschleuder, um arkane Geschosse zu erlernen. Wenn Ihr den Zauber gelernt habt, dann schießt zweimal erfolgreich arkane Geschosse auf eine Trainingsattrappe in Neu-Tüftlerstadt ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[26199] = { id = 26199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen. \n\n\"Doc\" Raddreh wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch neben der Gebäudeansammlung im Norden.", sourceObjective = "Trefft \"Doc\" Raddreh in Neu-Tüftlerstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26200] = { id = 26200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Priesters", description = "Es gibt eine einfache Technik, die ich Euch zeigen möchte. Sie ist recht simpel, aber eine der nützlichsten, die ich kenne.\n\nIhr könnt Euch selbst oder einen verwundeten Verbündeten sehr schnell mit ihr heilen. Sie ist äußerst praktisch, wenn Ihr jemanden prompt heilen müsst und keine Zeit für etwas Komplizierteres habt.\n\nProbiert die Technik aus und sagt mir Bescheid, wenn Ihr glaubt, sie gemeistert zu haben.", sourceObjective = "Sprecht mit \"Doc\" Raddreh, um Blitzheilung zu lernen. Wendet Blitzheilung 5-mal an verwundeten Infanteristen in Neu-Tüftlerstadt an.", sourceObjectiveStatus = "unverified-source-field" }
quests[26201] = { id = 26201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht eines Hexenmeisters", description = "Es überrascht mich nicht, dass es einem Hexenmeister wie Euch gelungen ist, sich den Weg aus Gnomeregan freizukämpfen. Nur wenige - selbst hier bei den Gnomen - verstehen den vollen Umfang der Macht, die wir ausüben. \n\nLasst mich Euch eine Beschwörung zeigen, die ich für nützlich halte. Dieser Zauber mit Namen Feuerbrand setzt Euer Ziel in Flammen und verursacht Schaden sofort und über einen gewissen Zeitraum. Setzt ihn weise ein, {name}, und Eure Feinde werden lernen, Euch zu fürchten.", sourceObjective = "Sprecht mit Alamar Grimm und lernt Feuerbrand. Dann wirkt Feuerbrand 5-mal auf eine Trainingsattrappe in Neu-Tüftlerstadt.", completion = "Wenn Ihr noch mächtiger geworden seid, kehrt zu mir zurück und ich werde Euch neue Zauber und Techniken lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26202] = { id = 26202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Wir werden all die Hilfe brauchen, die wir kriegen können, um unsere Heimat von den Troggs und den bestrahlten Gnomen zu befreien. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure, ähem... Künste zu erlernen.\n\nAlamar Grimm hält sich in dem Gebäude westlich von diesem hier auf. Er besitzt Kräfte, die den Euren gleichen. Er wird Euch helfen, Euch einzugewöhnen.", sourceObjective = "Sucht Alamar Grimm in Neu-Tüftlerstadt auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26203] = { id = 26203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nAusbildungsoffizier Dampfkurbel wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Er erwartet Euch auf dem kleinen Übungsfeld auf der anderen Straßenseite.", sourceObjective = "Sucht Ausbildungsoffizier Dampfkurbel in Neu-Tüftlerstadt auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26204] = { id = 26204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Kriegers", description = "Ich möchte Euch eine einfache, aber nützliche Technik zeigen.\n\nIch sage all meinen Rekruten, dass ein Krieger, der als erster zuschlägt, diesen Schwung nutzen kann, um die Oberhand zu gewinnen. Diese Technik wird aus der Entfernung benutzt, bevor Ihr den Kampf gegen Euren Gegner beginnt. Sie erlaubt Euch, heranzustürmen, den Gegner zu überraschen und zu betäuben.\n\nProbiert sie aus. Kehrt zu mir zurück, wenn Ihr glaubt, sie zu beherrschen.", sourceObjective = "Sprecht mit Ausbildungsoffizier Dampfkurbel, um Sturmangriff zu erlernen. Wendet Sturmangriff an einer Trainingsattrappe in Neu-Tüftlerstadt an.", sourceObjectiveStatus = "unverified-source-field" }
quests[26205] = { id = 26205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Aufgabe für den Multi-Bot", description = "Der Multi-Bot wird uns bei all den Aufgaben helfen, die für uns Gnome unangenehm oder gefährlich sind... sollte er funktionieren.\n\nAls Thermadraht seinen Verstrahler am Ende von Operation: Gnomeregan zündete, entstanden giftige Wolken. Giftschlamm begann unter dem alten Flugplatz südlich der Stadt hervorzubrodeln.\n\nWenn wir das nicht unter Kontrolle bekommen, könnte sich die Kontaminierung auf den Rest unseres Landes ausdehnen. Nehmt den Multi-Bot und bringt ihn in die Nähe der Geysire in den grünen Becken auf dem Toxischen Flugplatz. Der Bot sollte automatisch anspringen.", sourceObjective = "Benutzt den GS-9x Multi-Bot, um 5 toxische Geysire auf dem Toxischen Flugplatz zu säubern. Wenn Ihr nahe genug an einen Geysir herangekommen seid, wird der GS-9x Multi-Bot automatisch mit seiner Arbeit beginnen.", completion = "Wow, ich hätte nie gedacht, dass er auf Anhieb funktionieren würde!\n\nÄh, ich meine, wir hatten Erfolg! Ich frage mich, was man sonst noch mit diesem praktischen kleinen Kerl anfangen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26206] = { id = 26206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nKelsey Stahlfunken, ein wichtiges Mitglied des Geheimteams Gnomeregan, wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Ihr findet sie nordwestlich von hier im Ratszelt.", sourceObjective = "Sucht Kelsey Stahlfunken in Neu-Tüftlerstadt auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26207] = { id = 26207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Schurken", description = "Es gibt eine Technik, die ich Euch zeigen möchte.\n\nEine der wichtigsten Fähigkeiten des Schurken ist das Kombinieren von Schlägen. Dabei wird die Schwäche Eures Gegners ausgenutzt. Außerdem eröffnet Euch das die Möglichkeit, stärkere Manöver zu verwenden. Die Technik, die ich Euch beibringen möchte, nennt sich Ausweiden. Sie ist für das Ende einer Kombination vorgesehen, um Eurem Angriff ein starkes Ende zu verschaffen.\n\nWendet sie am besten nach einigen finsteren Stößen an.", sourceObjective = "Sprecht mit Kelsey Stahlfunken, um Ausweiden zu lernen. Sucht dann nach einer Trainingsattrappe in Neu-Tüftlerstadt und übt Ausweiden 3-mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26208] = { id = 26208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf wird fortgesetzt", description = "Die Zwerge von Eisenschmiede nahmen uns freundlicherweise auf, als die Trogginvasion und die Strahlung uns zum ersten Mal zwangen, Gnomeregan zu verlassen. Doch selbst die Hilfsbereitschaft von Freunden, kann das Heimweh nicht unterdrücken.\n\nIch habe um die Hilfe mutiger Gnome und anderer Mitglieder der Allianz gebeten. Gemeinsam wird es uns gelingen, die Kontrolle über Gnomeregan wiederzuerlangen und den Thronräuber Thermadraht ein für alle Mal zu besiegen.\n\nWir konnten mit Operation: Gnomeregan nicht alles erreichen, was wir uns vorgenommen hatten, aber Thermadraht ist auf der Flucht und wir sind unserer Heimat einen Schritt näher.", sourceObjective = "Betrachtet den Holo-Tisch vor Hochtüftler Mekkadrill, um mehr über Operation: Gnomeregan zu erfahren.", completion = "Im Moment wagen sich nur die Teams von S.I.C.H.E.R. hinunter in die Stadt, um nach Überlebenden zu suchen. Währenddessen hat Thermadraht einen seiner Anhänger, Ritzelstoß, ausgesandt, um uns abzulenken und sich selbst Zeit zu verschaffen, sich einzugraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26209] = { id = 26209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mordfall war der Fall, den sie mir gaben", description = "So sieht's aus, <Junge/Mädchen>, wir haben es mit einem ausgewachsenen Mordfall zu tun. Doppelter Homizid... Einfacher Pferd... izit.\n\nUnd was noch schlimmer ist, wir befinden uns hier in Westfall. Hier kann man mit einem einzigen Steinwurf haufenweise Landstreicher erwischen, die ein Motiv gehabt hätten, die Leute (und das Pferd) um die Ecke zu bringen.\n\nIch habe keine Ahnung, wer es war und ich bin ganz bestimmt nicht gerne hier in diesem Loch, um den Tod von ein paar Landbesetzern aufzuklären, aber ich möchte verdammt sein, wenn ich den Täter nicht dingfest machen kann. Ihr wollt helfen? Dann sprecht mit den Landstreichern. Die Vagabunden... kriegen alles mit.", sourceObjective = "Sprecht mit den verschiedenen Obdachlosen, die auf Jansens Hof leben, um Hinweise über die Brauenwirbelmorde zu sammeln.", progress = "Schon was herausgefunden?", completion = "Gnolle und Murlocs? Reiner Pferdemist, mein Junge! Das waren keine Gnolle oder Murlocs. Ich habe gesehen, was Gnolle und Murlocs mit ihren Opfern machen, und so ... sieht das nicht aus. Zu hübsch. Zu... perfekt.\n\nAußerdem haben die Brauenwirbels fünf Jahre lang auf diesem Gehöft gehockt. Nein, wer auch immer sie umgebracht hat, hatte einen Grund. Das hier ist Mord, ganz einfach, und wir werden der Sache auf den Grund gehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26210] = { id = 26210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammerita, Alter!", description = "Yo! Da is ne Schildkröte da draußen, die nicht wie die anderen is'. Das is' die Gammerita, Anführerin der Salzwasserschnappkiefer, 'ne richtig fiese Diebin!\n\nAlter, die hat mir meinen besten Köder geklaut. Einfach so abgebissen, hatse den! Seitdem beißen die Fisch nichmehr so an wie vorher.\n\nFinde Gammerita und hol' mir den Köder aus ihrem Bauch.", sourceObjective = "Katoom, der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Gammerita tötet und Katooms besten Köder aus ihrem Kadaver holt.\n\nKatoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.", progress = "Haste ihn gefunden?", completion = "ALTER! Das ist fantastisch! Mit meinem besten Köder und ohne die Schnappkiefern da, kommen die Fische sicher in Scharen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26211] = { id = 26211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappkiefer, Alter!", description = "Lasst Euch ja nicht von ihren großen Augen täuschen, Alter! Die Schnappkiefer da sind ne Bedrohung. Ich kann nicht mal für fünf Minuten angeln, ohne dass einer von diesen überdimensionalen Fisch-Staubsaugern mir meinen Köder klaut.\n\nTut mir und den Bruchhauern einen Gefallen und bringt sie um, Alter.\n\nBringt sie alle um!", sourceObjective = "Katoom der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 10 Salzwasserschnappkiefer tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", completion = "Mensch Alter! Ich kann Euch nicht genug danken! Hoffentlich ist diese Angelrute hier gut genug als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26212] = { id = 26212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lards vergessene Brotzeit", description = "Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Blutfratzentroll Lard mit großem Stock geschlagen hat. Lard zurück ins Dorf der Bruchhauer gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.", sourceObjective = "Lard aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\n\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Blutfratzen.", progress = "<Lard streicht sich über seinen riesigen Bauch.>\n\nLard so hungrig.", completion = "<Lard nimmt die riesige Fleischkeule von Euch und stopft sie sich in den Mund.>\n\nErste Sahne! Schön'n Dank.\n\nLard Euch machen tollen Picknickkorb für helfen Lard.", sourceObjectiveStatus = "unverified-source-field" }
quests[26213] = { id = 26213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf heißer Spur: Der Flusspfotenklan", description = "Da wir keine anderen Anhaltspunkte haben, können wir genauso gut auch den Informationen nachgehen, die Ihr erhalten habt.\n\nEs gibt einige Lager der Flusspfotengnolle hier in der Nähe. Macht sie ausfindig und sucht nach Hinweisen. Bringt mir was Ihr finden könnt. Beschränkt Eure Suche auf die Gnolle und die Späher der Flusspfoten.", sourceObjective = "Erhaltet den Hinweis der Flusspfotengnolle.", progress = "Habt Ihr etwas über die Gnolle herausgefunden?", completion = "Soll das so eine Art Witz sein? Ich lache nämlich nicht. Fetzen von rotem Stoff? Was zur Hölle soll das denn heißen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26214] = { id = 26214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Spur: Murlocs", description = "Egal für wie sinnlos ich diese Sache halte, wir müssen allen unseren Anhaltspunkten auf den Grund gehen.\n\nIch möchte, dass Ihr Euch hinaus zur Endlosen Küste begebt und den Murlocs dort ein wenig einheizt. Versucht einen Hinweis oder Informationen aufzuspüren, die etwas Licht in diesen Mordfall bringen können.\n\nKehrt zu mir zurück, falls Ihr Erfolg habt.", sourceObjective = "Findet den Murlochinweis.", progress = "Wie läuft die Murlocjagd?", completion = "Na klasse. Ich glaube, davon habe ich einen ganzen Stapel auf meinem Schreibtisch im Wachhaus. Wir stehen also wieder ganz am Anfang. Was wissen wir? Jemand, der gern Geschichten über die Vergangenheit schreibt hat den Brauenwirbels einen Brief geschickt.\n\nWir stecken anscheinend mitten in einer Geschichts...geschichte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26215] = { id = 26215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Lou Zweischuh", description = "Anscheinend haben wir hier einen echten Fall, Grünschnabel. Leider wollen die Anwohner offenbar nicht reden und die Anhaltspunkte, die Ihr von den Gnollen und Murlocs gewonnen habt, sind so gut wie wertlos. Wir müssen auf Plan... \"Haltet nach Lou Zweischuh Ausschau\" zurückgreifen.\n\nLou Zweischuh ist ein alter Informant von mir, der sich auf dem alten Kürbishof der Brauenwirbels niedergelassen hat. Geht nach Westen zu dem Gehöft und findet heraus, was Lou weiß.\n\nFalls er Euch irgendwelchen Mumpitz erzählt, sagt ihm, dass Horatio Euch schickt.", sourceObjective = "Sprecht mit Lou Zweischuh auf Brauenwirbels Kürbishof in Westfall.", completion = "Ganz ehrlich, wir haben einfach keinen Platz mehr für...\n\nHoratio schickt Euch? Na gut... ähm, wie kann ich Euch denn helfen?\n\nEr is' doch nich' hier, oder? Haha, er weiß doch sicher, dass ich mich nich' vor ihm versteckt hab. Hab mich nur für ein Weilchen bedeckt gehalten, versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26219] = { id = 26219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreis schließt sich", description = "Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat Ihr Nest in der Dämmerbucht, einer riesigen Unterwasserhöhle am Rand des Abgrunds.\n\nDieses Mal sind wir bereit. Die Gnome haben in Sturmwind eine wahre Schönheit für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.\n\nWenn die Zange X2 an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.", sourceObjective = "Geht von der Voldrins Mut aus an Bord der Zange X2 und helft dabei, Dämmerbucht zu sichern.", completion = "Gut gemacht, Gefreiter {name}.\n\nDie Chöhle ist unser, aber die Bestie ist entkommen. Wenn sie ihren chässlichen Kopf wieder zeigt, wir werden sie aus dem Wjasser sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26220] = { id = 26220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speck macht alles besser", description = "Eine Armee hungriger Orcs zu füttern ist nie einfach. Wir haben hier glücklicherweise gute Vorräte an Fleisch von ausgewachsenen Schweinen von den Schweinehöfen südlich von Orgrimmar. Tut mir einen Gefallen und schlachtet ein paar dieser Schweine für ihre köstlichen Schweinebäuche. Ich werde sie schneiden und gebratenen Speck für das Frühstück der Truppen vorbereiten.", sourceObjective = "Schlachtet einige der ausgewachsenen Schweine südlich von Orgrimmar und bringt mir 6 Schweinebäuche. Ich werde hier in der Gasse auf Euch warten.", progress = "Habt Ihr die Schweine schon geschlachtet?", completion = "Gute Arbeit, {name}. Das wird köstlicher Speck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26221] = { id = 26221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreis schließt sich", description = "Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat ihr Nest in der Schattenhöhle, einer riesigen Unterwasserhöhle im Wirbelnden Abgrund.\n\nDieses Mal sind wir bereit. Die Goblins haben sich als wertvolle Verbündete erwiesen und im Bilgewasserhafen eine bösartige Maschine für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.\n\nWenn die Verne an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.", sourceObjective = "Geht von der Höllenjuwel aus an Bord der Verne und helft dabei, die Schattenhöhle zu sichern.", completion = "Gut gemacht, {class}.\n\nDieses glitschige Vieh ist entkommen! Ich werde ein paar Verbesserungen vornehmen. Nächstes Mal hat es nicht so viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26222] = { id = 26222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteilte Teile", description = "Es gibt so viel zu tun und so wenige Gnome, die in der Lage sind, mir zu helfen! Der Hochtüftler hat mich gebeten, einige alte Bots und Teile der Operation: Gnomeregan auszuschlachten. Mit ein wenig Glück kann ich eine neue Reihe Multi-Bots demnächst in der Praxis testen!\n\nHättet Ihr vielleicht Zeit, um mir zu helfen? Es liegen alle möglichen Teile hier herum. Hebt alles auf, was Ihr findet, und bringt es mir. Wer weiß, was sich davon als nützlich erweist!", sourceObjective = "Bringt 7 Ersatzteile zu Ingenieur Schleiffunke in Neu-Tüftlerstadt.", progress = "Habt Ihr die Teile bekommen?", completion = "Die sind phantastisch! Mal sehen, was sich daraus basteln lässt. Hättet Ihr Interesse daran, den Prototyp zu testen, wenn ich fertig bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[26223] = { id = 26223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pirsch auf die Pirscher", description = "Viele mutige Trolle sind in der Wildnis von Hinterland verlorengegangen. Die Silbermähnenwölfe sind unseren Jägern die größte Gefahr. Sie lauern versteckt zwischen den Büschen und der Landschaft und greifen an, wenn es eine gute Gelegenheit gibt.\n\nWildheit dieser Art kann nicht ungestraft davonkommen!\n\nIhr müsst denken wie ein Silbermähnenwolf. Ihr müsst ihnen auflauern. Ihr müsst sie alle töten!", sourceObjective = "Tötet 8 Silbermähnenpirscher.", completion = "Gute Arbeit, {name}. Die Bruchhauer sind für Eure Hilfe sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26224] = { id = 26224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Wilden", description = "Unter all den bösartigen Tieren der Wildnis des Hinterlandes, sind auch die Eulenbestien zu finden. Schon so manche gute Krieger der Bruchhauer verloren wir an die grausamen Krallen und die Schnäbel der Biester.\n\nTötet jede wilde Eulenbestie, die Ihr finden könnt, {race}. Kehrt zu mir zurück, sobald Ihr von dem Blutbad genug habt. Euer Beitrag wird dann genau gewogen, abgemessen und bewertet.", sourceObjective = "Tötet 10 Wilde Eulenbestien.", completion = "Ihr habt Euch als ein wahrer Verbündeter der Bruchhauer erwiesen, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26225] = { id = 26225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupellyverbos' Portwein", description = "Ihr da! Wusstet Ihr, dass am Strand nördlich von hier dutzende Flaschen, wenn nicht hunderte Flaschen feinen Weins angeschwemmt wurden?\n\n...nun, jetzt wisst Ihr es!\n\nIch würde so viele nehmen, wie ich mit beiden Armen packen kann, wenn die Schildkröten nicht immer hinter mir her wären. Ich könnte schwören, sie wollen mein Blut!\n\nDa bezahle ich Euch doch lieber. Bringt mir 12 Flaschen Pupellyverbos' Portwein und ich werde ihn Euch \"abkaufen\", {class}.", sourceObjective = "Sammelt 12 Flaschen Pupellyverbos' Portwein.", progress = "Habt Ihr zwölf Flaschen? Zählen kann ich, keine Sorge!", completion = "Wunderbar. Ich wüsste nicht, wo ich das Zeug herkriegen würde, wenn nicht immer wieder betrunkene Menschen mit ihren Schiffen aufliefen.\n\nNormalerweise würde ich auch erstmal mit Euch feilschen, aber Ihr habt Glück, denn ich kann es kaum erwarten, mir ein Schlückchen zu genehmigen. Prost!", sourceObjectiveStatus = "unverified-source-field" }
quests[26226] = { id = 26226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusskrebs à la Creole", description = "Um Orgrimmar herum befinden sich mehrere kleine Seen. In den Seen wimmelt es jedes Jahr von Flusskrebsen. Hier kommt Ihr ins Spiel, {name}. Ihr müsst für mich diese köstlichen Krustentiere fangen und sie mir bringen, wenn Ihr fertig seid. Wenn Ihr erfolgreich seid, wird unsere Armee heute abend ein Festmahl genießen.", sourceObjective = "Fangt 10 schlammige Flusskrebse in Orgrimmar und bringt die Krustentiere zu Marogg, wenn Ihr fertig seid.", progress = "Konntet Ihr ein paar Flusskrebse fangen?", completion = "Uff, gerne gekocht habe ich diese schleimigen Dinger nie. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26227] = { id = 26227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, die Frucht beißt zurück!", description = "Manchmal wollen unsere Streitkräfte auch etwas Süßes. Ich geben ihnen nicht immer, was sie wollen, aber heute werde ich eine Ausnahme machen. Sicherlich habt Ihr schon die einheimischen Kakteen gesehen, die in Orgrimmar wachsen. Die Kakteen tragen eine sehr leckere Delikatesse, die Kaktusfeigenfrucht. Das Problem ist, dass die Frucht voller Kaktusnadeln ist! Passt auf Eure Hände auf und bringt mir ein paar Früchte.", sourceObjective = "Sammelt 8 Kaktusfeigenfrüchte und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr genug Früchte finden?", completion = "Lasst mich Eure Hände sehen... aha! Ihr seid beim Pflücken dieser Frucht auch nicht besser als ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[26228] = { id = 26228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Made im Speck", description = "Hört zu, eigentlich sollte ich gar nich' mit Euch reden, aber ich schulde Horatio den einen oder anderen Gefallen. Ich weiß eigenlich gar nichts darüber, was mit den Brauenwirbels passiert is', aber vielleicht kann ich Euch trotzdem weiterhelfen.\n\n<Lou reicht Euch eine große Kiste.>\n\nDiese Kiste war mein Zuhause, bevor ich reich geworden bin. Jetzt führ' ich ein Leben, von dem jeder Landstreicher träumt!\n\nAlso, Ihr schnappt Euch jetzt mal diese Wohnkiste hier und macht Euch auf zum Jangoschacht südwestlich von hier. Dringt bis ans Ende der Mine vor und versteckt Euch dort in der Kiste.", sourceObjective = "Benutzt Lou Zweischuhs altes Haus am Ende des Jangoschachtes in Westfall.", completion = "<Lou hält sich die Ohren zu und fängt an, laut zu sprechen.>\n\nHALT! HALT! HALT! Ich will's gar nich' hören! Ich will's nich' wissen und egal is' es mir auch! Solche Informationen können einen in der Gegend hier das Leben kosten.\n\nEins kann ich Euch noch verraten und das war's dann!", sourceObjectiveStatus = "unverified-source-field" }
quests[26229] = { id = 26229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Ich NEHMEN Kerze!\"", description = "Bevor diese verdammten Kobolde mir mein Hinkebein verpasst haben, war ich William Pestles bester Kerzenlieferant. Von mir kommt sogar der Ausspruch \"ICH NEHMEN KERZE!\" Jep, das war ich. Die Kobolde haben immer gerufen \"Du nicht nehmen Kerze!\" und ich hab geantwortet \"ICH NEHMEN KERZE!\" und ihnen den Schädel eingeschlagen!\n\n<Jimb träumt einen Moment lang.>\n\nDas waren gute Zeiten... Die besten Zeiten.\n\nUnd jetzt? Ich kann noch nicht mal ohne Hilfe auf die Toilette gehen. Wollt Ihr mir helfen? Tötet ein paar Kobolde für mich. Ihr solltet einen ganzen Haufen von denen in der Mine hier in der Nähe finden.", sourceObjective = "Tötet 12 Koboldbuddler.", completion = "Ah, SÜSSE Gerechtigkeit! Diese Kobolde abzuschlachten wird mich nicht dazu bringen, wieder wie ein normaler {race} zu laufen, und es wird mir auch mit Sicherheit keine Arbeit einbringen, aber es tut auf jeden Fall verdammt gut.\n\n\n\nHier, ich habe da etwas für Euch aus meiner Zeit als Koboldjäger. Vielleicht könnt Ihr damit etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26230] = { id = 26230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festmahl oder Hungersnot", description = "Das Leben in Westfall ist schwer, <Söhnchen/Mädchen>! Jeder Tag ist ein Kampf. Manchmal vergehen Wochen zwischen anständigen Mahlzeiten. Deswegen ist es so wichtig, dass wir uns gegenseitig beistehen. Vielleicht könnt Ihr ja mit anpacken, hm? Ich backe Matschkuchen und benötige noch ein paar Zutaten.\n\nBesorgt mir etwas frischen Matsch vom Kürbisbeet vor dem Haus und ein paar Kojotenschwänze. Ihr könnt überall in der Wildnis von Westfall Kojoten finden.\n\nAn die Arbeit! Wir haben Mägen zu füllen.", sourceObjective = "Sammelt 6 Kojotenschwänze und 5 Handvoll frischen Matsch.", progress = "Matschkuchen backen sich nicht von selbst - normalerweise.", completion = "Mir knurrt schon der Magen, wenn ich Euch nur rieche! Wir werden heut' Abend fürstlich essen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26232] = { id = 26232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lous Abschiedsworte", description = "So ein paar Rohlinge sind vor kurzem auf dem Gehöft aufgetaucht und haben 'ne Menge Ärger verursacht. Keine Ahnung, wo die herkommen oder für wen die arbeiten, aber ich bin mir SICHER, dass sie nichts Gutes im Schilde führen. Ich hab' sie vielleicht über so ein paar Dinge sprechen hören, die Euch interessieren könnten.\n\nWenn Ihr Interesse habt, findet ihr die Rohlinge hinter'm Bauernhaus. Wenn man Euch ertappt oder umbringt, ich weiß nichts von Euch. Hab Euch noch nie im Leben gesehen!\n\nViel Glück, <Junge/Mädel>.", sourceObjective = "Belauscht die Rohlinge hinter dem Bauernhaus auf Brauenwirbels Kürbishof in Westfall.", completion = "Wir haben es hier mit einer Organisation zu tun, Grünschnabel. Niemand bringt so einfach am helllichten Tage den reichsten Landstreicher von Westfall um, ohne dabei Zeugen zu hinterlassen. Hinter diesen Morden steckt jemand mit einer Menge Macht. Was habt Ihr bisher in Erfahrung bringen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[26233] = { id = 26233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den eigenen Reihen stehlen", description = "Wie Ihr wisst, {name}, hat Garrosh die Trolle von Orgrimmar in die westlichen Außengebiete der Stadt befehligt. Zu unserem Glück bedeutet das, dass wir leicht an ihre Vorräte kommen. Ich bereite gerade eine große Portion Jambalaya für die Infanterie vor und brauche so viel Reis, wie ich bekommen kann. Die Trolle lagern Reis in den Fässern in der Nähe ihrer Behausungen. Bringt mir die Fässer mit Dunkelspeerreis und ich kann das Gericht fertigstellen.", sourceObjective = "Bringt 6 Fässer mit Dunkelspeerreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr den Reis besorgen?", completion = "Ihr habt auch Talent im Stehlen, wie ich sehe, {name}. Sorgt Euch nicht, wir werden den Reis zurückbringen, wenn wir fertig sind... oder auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26234] = { id = 26234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den eigenen Reihen stehlen", description = "Wie Ihr wisst, {name}, hat Garrosh die Goblins von Orgrimmar in die westlichen Außengebiete der Stadt befehligt. Zu unserem Glück bedeutet das, dass wir leicht an ihre Vorräte kommen. Ich bereite gerade eine große Portion Jambalaya für die Infanterie vor und brauche so viel Reis, wie ich bekommen kann. Die Goblins lagern Reis in den Fässern in der Nähe ihrer Behausungen. Bringt mir die Fässer mit Kezanreis und ich kann das Gericht fertigstellen.", sourceObjective = "Bringt 6 Fässer mit Kezanreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr den Reis besorgen?", completion = "Ihr habt auch Talent im Stehlen, wie ich sehe, {name}. Sorgt Euch nicht, wir werden den Reis zurückbringen, wenn wir fertig sind... oder auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26235] = { id = 26235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Diebe bekommen Hunger", description = "Seit ein paar Wochen haben wir hier in Orgrimmar Probleme mit Dieben, die die Rationen der Infanterie stehlen. Vor Kurzem habe ich Informationen darüber erhalten, wo diese Diebstähle stattfinden. Wenn Ihr irgendwo Kisten und Vorräte seht, könnt Ihr davon ausgehen, dass die Diebe nicht weit sind. Ich möchte, dass Ihr diese Diebe ausfindig macht und die gestohlenen Rationen findet. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Findet 3 Infanterierationen der Horde und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr die Rationen finden?", completion = "Gute Arbeit, {name}! Ich werde dafür sorgen, dass die Rationen umgehend wieder zu unseren Truppen kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26236] = { id = 26236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vernehmung der Saldeans", description = "Was wissen wir also bisher? Wir müssen unseren Anhaltspunkten folgen.\n\nDrüben auf Jansens Hof habt Ihr einen durchnässten Brief und ein paar rote Stofffetzen gefunden. Hier auf dem Hof der Brauenwirbels habt Ihr ein Gespräch zwischen einer merkwürdigen Gestalt und einem Ogermagier belauscht. Ihr habt außerdem die Geständnisse von ein paar Schlägern, den Mord begangen zu haben - woraufhin Ihr die Schläger getötet habt.\n\nDa passt Einiges nicht zusammen, Grünschnabel.\n\nSüdöstlich von hier lebt ein älteres Ehepaar auf Saldeans Hof. Macht Euch auf den Weg dorthin und sprecht mit Bauer Saldean. Findet heraus, was er weiß.", sourceObjective = "Sprecht mit Bauer Saldean auf Saldeans Hof in Westfall.", completion = "Horatio Laine? Der Mann ist ein Drecksack. So dreckig wie meine Unterwäsche.\n\nHört zu, mein Freund, ich erteile nicht oft solche Ratschläge, aber Ihr scheint mir ein aufrichtiger Mann zu sein. VERSCHWINDET AUS WESTFALL. Ihr steckt schon bis über beide Ohren im Mist. Was Ihr da gerade macht ist so, als würdet Ihr Euren Kopf unter's Beil legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26237] = { id = 26237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeiten sind schwer", description = "Das sind schwere Zeiten, <Bruder/Schwester>. Da jetzt die geknechteten Massen aus Sturmwind hierher nach Westfall auswandern, sind unsere Vorräte knapper denn je. Das Volk ist unruhig und braucht Hilfe.\n\nUnser Farmhaus dient schon seit Jahren als Behelfsunterkunft. Salma gibt sich alle Mühe, unsere Gäste am Leben zu erhalten, aber manchmal werden sie von den Erntebehütern erwischt. Das sind diese missratenen Ungetüme, die sich auf meinem Feld herumtreiben - ein kleines Geschenk, das die Defias zurückgelassen haben, als sie vertrieben wurden. Helft uns!", sourceObjective = "Tötet 10 Erntebehüter.", completion = "Danke, Bruder. Ihr habt Salma und mir einen großen Dienst erwiesen und ich verspreche Euch, dass wir das so schnell nicht vergessen werden. Viel Geld habe ich nicht, aber Ihr könnt Euch gern an dem Bisschen bedienen, das ich habe.", sourceObjectiveStatus = "unverified-source-field" }
